1	import { useEffect } from 'react';
2	import { ThemeMode } from 'shared/types';
3	import { useTheme } from '@/shared/hooks/useTheme';
4	
5	interface VibeStyleOverrideMessage {
6	  type: 'VIBE_STYLE_OVERRIDE';
7	  payload:
8	    | {
9	        kind: 'cssVars';
10	        variables: Record<string, string>;
11	      }
12	    | {
13	        kind: 'theme';
14	        theme: ThemeMode;
15	      };
16	}
17	
18	interface VibeIframeReadyMessage {
19	  type: 'VIBE_IFRAME_READY';
20	}
21	
22	// Component that adds postMessage listener for style overrides
23	export function AppWithStyleOverride({
24	  children,
25	  setTheme,
26	}: {
27	  children: React.ReactNode;
28	  setTheme: (theme: ThemeMode) => void;
29	}) {
30	  useEffect(() => {
31	    function handleStyleMessage(event: MessageEvent) {
32	      if (event.data?.type !== 'VIBE_STYLE_OVERRIDE') return;
33	
34	      // Origin validation (only if VITE_PARENT_ORIGIN is configured)
35	      const allowedOrigin = import.meta.env.VITE_PARENT_ORIGIN;
36	      if (allowedOrigin && event.origin !== allowedOrigin) {
37	        console.warn(
38	          '[StyleOverride] Message from unauthorized origin:',
39	          event.origin
40	        );
41	        return;
42	      }
43	
44	      const message = event.data as VibeStyleOverrideMessage;
45	
46	      // CSS variable overrides (only --vibe-* prefixed variables)
47	      if (
48	        message.payload.kind === 'cssVars' &&
49	        typeof message.payload.variables === 'object'
50	      ) {
51	        Object.entries(message.payload.variables).forEach(([name, value]) => {
52	          if (typeof value === 'string') {
53	            document.documentElement.style.setProperty(name, value);
54	          }
55	        });
56	      } else if (message.payload.kind === 'theme') {
57	        setTheme(message.payload.theme);
58	      }
59	    }
60	
61	    window.addEventListener('message', handleStyleMessage);
62	    return () => window.removeEventListener('message', handleStyleMessage);
63	  }, [setTheme]);
64	
65	  // Send ready message to parent when component mounts
66	  useEffect(() => {
67	    const allowedOrigin = import.meta.env.VITE_PARENT_ORIGIN;
68	
69	    // Only send if we're in an iframe and have a parent
70	    if (window.parent && window.parent !== window) {
71	      const readyMessage: VibeIframeReadyMessage = {
72	        type: 'VIBE_IFRAME_READY',
73	      };
74	
75	      // Send to specific origin if configured, otherwise send to any origin
76	      const targetOrigin = allowedOrigin || '*';
77	      window.parent.postMessage(readyMessage, targetOrigin);
78	    }
79	  }, []);
80	
81	  return <>{children}</>;
82	}
83	
84	export function useStyleOverrideThemeSetter() {
85	  const { setTheme } = useTheme();
86	  return setTheme;
87	}
