1	import type {
2	  PatchTypeWithKey,
3	  DisplayEntry,
4	  AggregatedPatchGroup,
5	  AggregatedDiffGroup,
6	  AggregatedThinkingGroup,
7	  ToolAggregationType,
8	} from '@/shared/hooks/useConversationHistory/types';
9	
10	/**
11	 * Checks if a patch entry is a user_message entry.
12	 */
13	function isUserMessage(entry: PatchTypeWithKey): boolean {
14	  if (entry.type !== 'NORMALIZED_ENTRY') return false;
15	  return entry.content.entry_type.type === 'user_message';
16	}
17	
18	/**
19	 * Checks if a patch entry is a thinking entry.
20	 */
21	function isThinkingEntry(entry: PatchTypeWithKey): boolean {
22	  if (entry.type !== 'NORMALIZED_ENTRY') return false;
23	  return entry.content.entry_type.type === 'thinking';
24	}
25	
26	/**
27	 * Extracts the file path from a file_edit entry, or null if not a file_edit entry.
28	 */
29	function getFileEditPath(entry: PatchTypeWithKey): string | null {
30	  if (entry.type !== 'NORMALIZED_ENTRY') return null;
31	
32	  const entryType = entry.content.entry_type;
33	  if (entryType.type !== 'tool_use') return null;
34	
35	  const { action_type } = entryType;
36	  if (action_type.action === 'file_edit') {
37	    return action_type.path;
38	  }
39	
40	  return null;
41	}
42	
43	/**
44	 * Determines if a patch entry can be aggregated and returns its aggregation type.
45	 * Handles file_read, search, web_fetch, and command_run (categorized by command type).
46	 */
47	function getAggregationType(
48	  entry: PatchTypeWithKey
49	): ToolAggregationType | null {
50	  if (entry.type !== 'NORMALIZED_ENTRY') return null;
51	
52	  const entryType = entry.content.entry_type;
53	  if (entryType.type !== 'tool_use') return null;
54	
55	  const { action_type } = entryType;
56	  if (action_type.action === 'file_read') return 'file_read';
57	  if (action_type.action === 'search') return 'search';
58	  if (action_type.action === 'web_fetch') return 'web_fetch';
59	
60	  if (action_type.action === 'command_run') {
61	    const category = action_type.category;
62	    if (
63	      category === 'read' ||
64	      category === 'search' ||
65	      category === 'edit' ||
66	      category === 'fetch'
67	    ) {
68	      return `command_run_${category}`;
69	    }
70	  }
71	
72	  return null;
73	}
74	
75	/**
76	 * First pass: group consecutive thinking entries within each turn (between user messages)
77	 * for all turns except the last one.
78	 */
79	function aggregateThinkingInPreviousTurns(
80	  entries: PatchTypeWithKey[]
81	): PatchTypeWithKey[] {
82	  if (entries.length === 0) return [];
83	
84	  // Find all user message indices
85	  const userMessageIndices: number[] = [];
86	  entries.forEach((entry, index) => {
87	    if (isUserMessage(entry)) {
88	      userMessageIndices.push(index);
89	    }
90	  });
91	
92	  // If there's 0 or 1 user message, no "previous" turns exist
93	  if (userMessageIndices.length <= 1) {
94	    return entries;
95	  }
96	
97	  // The last user message index marks the start of the "current" turn
98	  const lastUserMessageIndex =
99	    userMessageIndices[userMessageIndices.length - 1];
100	
101	  // Process entries, grouping thinking entries in previous turns
102	  const result: PatchTypeWithKey[] = [];
103	  let currentThinkingGroup: PatchTypeWithKey[] = [];
104	
105	  const flushThinkingGroup = () => {
106	    if (currentThinkingGroup.length === 0) return;
107	
108	    if (currentThinkingGroup.length === 1) {
109	      // Single thinking entry - create a group anyway for consistency in collapsed view
110	      const entry = currentThinkingGroup[0];
111	      const aggregatedGroup: AggregatedThinkingGroup = {
112	        type: 'AGGREGATED_THINKING_GROUP',
113	        entries: [...currentThinkingGroup],
114	        patchKey: `agg-thinking:${entry.patchKey}`,
115	        executionProcessId: entry.executionProcessId,
116	      };
117	      // Cast to PatchTypeWithKey to maintain the array type
118	      result.push(aggregatedGroup as unknown as PatchTypeWithKey);
119	    } else {
120	      // Multiple entries - create an aggregated thinking group
121	      const firstEntry = currentThinkingGroup[0];
122	      const aggregatedGroup: AggregatedThinkingGroup = {
123	        type: 'AGGREGATED_THINKING_GROUP',
124	        entries: [...currentThinkingGroup],
125	        patchKey: `agg-thinking:${firstEntry.patchKey}`,
126	        executionProcessId: firstEntry.executionProcessId,
127	      };
128	      // Cast to PatchTypeWithKey to maintain the array type
129	      result.push(aggregatedGroup as unknown as PatchTypeWithKey);
130	    }
131	
132	    currentThinkingGroup = [];
133	  };
134	
135	  for (let i = 0; i < entries.length; i++) {
136	    const entry = entries[i];
137	    const isInPreviousTurn = i < lastUserMessageIndex;
138	
139	    // Track turn boundaries
140	    if (isUserMessage(entry)) {
141	      // Flush any pending thinking group before the user message
142	      flushThinkingGroup();
143	      result.push(entry);
144	      continue;
145	    }
146	
147	    // Only aggregate thinking entries in previous turns
148	    if (isInPreviousTurn && isThinkingEntry(entry)) {
149	      currentThinkingGroup.push(entry);
150	    } else {
151	      // Flush any pending thinking group
152	      flushThinkingGroup();
153	      result.push(entry);
154	    }
155	  }
156	
157	  // Flush any remaining thinking group
158	  flushThinkingGroup();
159	
160	  return result;
161	}
162	
163	/**
164	 * Aggregates consecutive entries of the same aggregatable type (file_read, search, web_fetch)
165	 * into grouped entries for accordion-style display.
166	 *
167	 * Also aggregates consecutive file_edit entries for the same file path.
168	 * Also aggregates thinking entries in previous conversation turns.
169	 *
170	 * Rules:
171	 * - Only group entries of the same type that follow each other consecutively
172	 * - For file_edit entries, also group by file path
173	 * - Thinking entries in previous turns (before the last user message) are collapsed
174	 * - Preserve the original order of entries
175	 * - Single entries of an aggregatable type are NOT grouped (returned as-is)
176	 * - At least 2 consecutive entries of the same type are required to form a group
177	 */
178	export function aggregateConsecutiveEntries(
179	  entries: PatchTypeWithKey[]
180	): DisplayEntry[] {
181	  if (entries.length === 0) return [];
182	
183	  // First pass: aggregate thinking entries in previous turns
184	  const entriesWithThinkingAggregated =
185	    aggregateThinkingInPreviousTurns(entries);
186	
187	  const result: DisplayEntry[] = [];
188	
189	  // State for tool aggregation (file_read, search, web_fetch, command_run_*)
190	  let currentToolGroup: PatchTypeWithKey[] = [];
191	  let currentAggregationType: ToolAggregationType | null = null;
192	
193	  // State for diff aggregation (file_edit by path)
194	  let currentDiffGroup: PatchTypeWithKey[] = [];
195	  let currentDiffPath: string | null = null;
196	
197	  const flushToolGroup = () => {
198	    if (currentToolGroup.length === 0) return;
199	
200	    if (currentToolGroup.length === 1) {
201	      // Single entry - don't aggregate, return as-is
202	      result.push(currentToolGroup[0]);
203	    } else {
204	      // Multiple entries - create an aggregated group
205	      const firstEntry = currentToolGroup[0];
206	      const aggregatedGroup: AggregatedPatchGroup = {
207	        type: 'AGGREGATED_GROUP',
208	        aggregationType: currentAggregationType!,
209	        entries: [...currentToolGroup],
210	        patchKey: `agg:${firstEntry.patchKey}`,
211	        executionProcessId: firstEntry.executionProcessId,
212	      };
213	      result.push(aggregatedGroup);
214	    }
215	
216	    currentToolGroup = [];
217	    currentAggregationType = null;
218	  };
219	
220	  const flushDiffGroup = () => {
221	    if (currentDiffGroup.length === 0) return;
222	
223	    if (currentDiffGroup.length === 1) {
224	      // Single entry - don't aggregate, return as-is
225	      result.push(currentDiffGroup[0]);
226	    } else {
227	      // Multiple entries for same file - create an aggregated diff group
228	      const firstEntry = currentDiffGroup[0];
229	      const aggregatedDiffGroup: AggregatedDiffGroup = {
230	        type: 'AGGREGATED_DIFF_GROUP',
231	        filePath: currentDiffPath!,
232	        entries: [...currentDiffGroup],
233	        patchKey: `agg-diff:${firstEntry.patchKey}`,
234	        executionProcessId: firstEntry.executionProcessId,
235	      };
236	      result.push(aggregatedDiffGroup);
237	    }
238	
239	    currentDiffGroup = [];
240	    currentDiffPath = null;
241	  };
242	
243	  for (const entry of entriesWithThinkingAggregated) {
244	    // Check if this is already an aggregated thinking group (from first pass)
245	    if (
246	      (entry as unknown as AggregatedThinkingGroup).type ===
247	      'AGGREGATED_THINKING_GROUP'
248	    ) {
249	      flushToolGroup();
250	      flushDiffGroup();
251	      result.push(entry as unknown as DisplayEntry);
252	      continue;
253	    }
254	
255	    const aggregationType = getAggregationType(entry);
256	    const fileEditPath = getFileEditPath(entry);
257	
258	    // Handle file_edit entries
259	    if (fileEditPath !== null) {
260	      // Flush any pending tool group first
261	      flushToolGroup();
262	
263	      if (currentDiffPath === null) {
264	        // Start a new diff group
265	        currentDiffPath = fileEditPath;
266	        currentDiffGroup.push(entry);
267	      } else if (fileEditPath === currentDiffPath) {
268	        // Same file - add to current diff group
269	        currentDiffGroup.push(entry);
270	      } else {
271	        // Different file - flush current diff group and start new one
272	        flushDiffGroup();
273	        currentDiffPath = fileEditPath;
274	        currentDiffGroup.push(entry);
275	      }
276	    }
277	    // Handle tool aggregation (file_read, search, web_fetch)
278	    else if (aggregationType !== null) {
279	      // Flush any pending diff group first
280	      flushDiffGroup();
281	
282	      if (currentAggregationType === null) {
283	        // Start a new tool group
284	        currentAggregationType = aggregationType;
285	        currentToolGroup.push(entry);
286	      } else if (aggregationType === currentAggregationType) {
287	        // Same type - add to current group
288	        currentToolGroup.push(entry);
289	      } else {
290	        // Different aggregatable type - flush current group and start new one
291	        flushToolGroup();
292	        currentAggregationType = aggregationType;
293	        currentToolGroup.push(entry);
294	      }
295	    }
296	    // Non-aggregatable entry
297	    else {
298	      // Flush any pending groups and add this entry
299	      flushToolGroup();
300	      flushDiffGroup();
301	      result.push(entry);
302	    }
303	  }
304	
305	  // Flush any remaining groups
306	  flushToolGroup();
307	  flushDiffGroup();
308	
309	  return result;
310	}
