104	export class ApiError<E = unknown> extends Error {
105	  public status?: number;
106	  public error_data?: E;
107	
108	  constructor(
109	    message: string,
110	    public statusCode?: number,
111	    public response?: Response,
112	    error_data?: E
113	  ) {
114	    super(message);
115	    this.name = 'ApiError';
116	    this.status = statusCode;
117	    this.error_data = error_data;
118	  }
119	}
