93	/** Extracts attachment IDs from `attachment://` references in markdown content. */
94	export function extractAttachmentIds(content: string): Set<string> {
95	  const ids = new Set<string>();
96	  const regex = /attachment:\/\/([a-f0-9-]+)/g;
97	  let match;
98	  while ((match = regex.exec(content)) !== null) {
99	    ids.add(match[1]);
100	  }
101	  return ids;
102	}
103	
104	export function replaceAttachmentSource(
105	  content: string,
106	  previousSrc: string,
107	  nextSrc: string
108	): { content: string; replaced: boolean } {
109	  const matches = findAttachmentMarkdownMatches(content).filter(
110	    (match) => match.src === previousSrc
111	  );
112	
113	  if (matches.length === 0) {
114	    return { content, replaced: false };
115	  }
116	
117	  let nextContent = content;
118	
119	  for (const match of matches.reverse()) {
120	    const replacement = `${match.prefix}[${match.label}](${nextSrc})`;
121	    nextContent =
122	      nextContent.slice(0, match.start) +
123	      replacement +
124	      nextContent.slice(match.end);
125	  }
126	
127	  return {
128	    content: nextContent,
129	    replaced: true,
130	  };
131	}
132	
133	export function removeAttachmentMarkdownBySource(
134	  content: string,
135	  src: string
136	): { content: string; removed: boolean } {
137	  const matches = findAttachmentMarkdownMatches(content).filter(
138	    (match) => match.src === src
139	  );
140	
141	  if (matches.length === 0) {
142	    return { content, removed: false };
143	  }
144	
145	  let nextContent = content;
146	  for (const match of matches.reverse()) {
147	    nextContent = removeAttachmentSlice(nextContent, match.start, match.end);
148	  }
149	
150	  return { content: nextContent, removed: true };
151	}
