1	import { ApiError, oauthApi } from '@/shared/lib/api';
2	import { queryClient } from '@/shared/lib/queryClient';
3	import { shouldRefreshAccessToken } from 'shared/jwt';
4	
5	const TOKEN_QUERY_KEY = ['auth', 'token'] as const;
6	const TOKEN_STALE_TIME = 125 * 1000;
7	
8	type RefreshStateCallback = (isRefreshing: boolean) => void;
9	type PauseableShape = { pause: () => void; resume: () => void };
10	
11	function isUnauthorizedError(error: unknown): boolean {
12	  return error instanceof ApiError && error.statusCode === 401;
13	}
14	
15	class TokenManager {
16	  private isRefreshing = false;
17	  private refreshPromise: Promise<string | null> | null = null;
18	  private subscribers = new Set<RefreshStateCallback>();
19	  private pauseableShapes = new Set<PauseableShape>();
20	
21	  /**
22	   * Get a valid access token, refreshing if needed.
23	   * Returns null immediately if the user is not logged in.
24	   */
25	  async getToken(): Promise<string | null> {
26	    if (this.refreshPromise) {
27	      return this.refreshPromise;
28	    }
29	
30	    // Skip token fetch if user is not logged in — avoids unnecessary 401s
31	    // from Electric shapes or other background requests after logout.
32	    const cachedSystem = queryClient.getQueryData<{
33	      login_status?: { status: string };
34	    }>(['user-system']);
35	    if (cachedSystem && cachedSystem.login_status?.status !== 'loggedin') {
36	      return null;
37	    }
38	
39	    const cachedData = queryClient.getQueryData<{
40	      access_token?: string;
41	    }>(TOKEN_QUERY_KEY);
42	    const cachedToken = cachedData?.access_token;
43	    if (!cachedToken || shouldRefreshAccessToken(cachedToken)) {
44	      await queryClient.invalidateQueries({ queryKey: TOKEN_QUERY_KEY });
45	    }
46	
47	    try {
48	      const data = await queryClient.fetchQuery({
49	        queryKey: TOKEN_QUERY_KEY,
50	        queryFn: () => oauthApi.getToken(),
51	        staleTime: TOKEN_STALE_TIME,
52	      });
53	      return data?.access_token ?? null;
54	    } catch (error) {
55	      if (isUnauthorizedError(error)) {
56	        await this.handleUnauthorized();
57	      }
58	      return null;
59	    }
60	  }
61	
62	  /**
63	   * Force a token refresh. Call this when you receive a 401 response.
64	   * Coordinates multiple callers to prevent concurrent refresh attempts.
65	   *
66	   * Returns the new token (or null if refresh failed).
67	   */
68	  triggerRefresh(): Promise<string | null> {
69	    // CRITICAL: Assign promise SYNCHRONOUSLY so concurrent 401 handlers share one refresh.
70	    this.refreshPromise ??= this.doRefresh();
71	    return this.refreshPromise;
72	  }
73	
74	  /**
75	   * Register an Electric shape for pause/resume during token refresh.
76	   * When refresh starts, all shapes are paused to prevent 401 spam.
77	   * When refresh completes, shapes are resumed.
78	   *
79	   * Returns an unsubscribe function.
80	   */
81	  registerShape(shape: PauseableShape): () => void {
82	    this.pauseableShapes.add(shape);
83	    // If currently refreshing, pause immediately
84	    if (this.isRefreshing) {
85	      shape.pause();
86	    }
87	    return () => this.pauseableShapes.delete(shape);
88	  }
89	
90	  /**
91	   * Get the current refreshing state synchronously.
92	   */
93	  getRefreshingState(): boolean {
94	    return this.isRefreshing;
95	  }
96	
97	  /**
98	   * Subscribe to refresh state changes.
99	   * Returns an unsubscribe function.
100	   */
101	  subscribe(callback: RefreshStateCallback): () => void {
102	    this.subscribers.add(callback);
103	    return () => this.subscribers.delete(callback);
104	  }
105	
106	  private async doRefresh(): Promise<string | null> {
107	    // Skip refresh if user is already logged out — avoids unnecessary 401s
108	    // from Electric shapes or other background requests after logout.
109	    const cachedSystem = queryClient.getQueryData<{
110	      login_status?: { status: string };
111	    }>(['user-system']);
112	    if (cachedSystem && cachedSystem.login_status?.status !== 'loggedin') {
113	      // Pause shapes so they stop making requests while logged out
114	      this.pauseShapes();
115	      return null;
116	    }
117	
118	    this.setRefreshing(true);
119	    this.pauseShapes();
120	
121	    try {
122	      // Invalidate the cache to force a fresh fetch
123	      await queryClient.invalidateQueries({ queryKey: TOKEN_QUERY_KEY });
124	
125	      // Fetch fresh token
126	      const data = await queryClient.fetchQuery({
127	        queryKey: TOKEN_QUERY_KEY,
128	        queryFn: () => oauthApi.getToken(),
129	        staleTime: TOKEN_STALE_TIME,
130	      });
131	
132	      const token = data?.access_token ?? null;
133	      if (token) {
134	        this.resumeShapes();
135	      }
136	      return token;
137	    } catch (error) {
138	      if (isUnauthorizedError(error)) {
139	        await this.handleUnauthorized();
140	      }
141	      return null;
142	    } finally {
143	      this.refreshPromise = null;
144	      this.setRefreshing(false);
145	    }
146	  }
147	
148	  private async handleUnauthorized(): Promise<void> {
149	    // Check if the user was previously logged in before we invalidate.
150	    // If they're already logged out, 401s are expected — don't show the dialog.
151	    const cachedSystem = queryClient.getQueryData<{
152	      login_status?: { status: string };
153	    }>(['user-system']);
154	    const wasLoggedIn = cachedSystem?.login_status?.status === 'loggedin';
155	
156	    // Pause shapes — session is invalid, prevent further 401s
157	    this.pauseShapes();
158	
159	    // Reload system state so the UI transitions to logged-out
160	    await queryClient.invalidateQueries({ queryKey: ['user-system'] });
161	
162	    // Only show the login dialog if the user was previously logged in
163	    // (i.e., their session expired unexpectedly). Don't prompt users who
164	    // intentionally logged out or were never logged in.
165	    if (wasLoggedIn) {
166	      const { OAuthDialog } = await import(
167	        '@/shared/dialogs/global/OAuthDialog'
168	      );
169	      void OAuthDialog.show({});
170	    }
171	  }
172	
173	  private setRefreshing(value: boolean): void {
174	    this.isRefreshing = value;
175	    this.subscribers.forEach((cb) => cb(value));
176	  }
177	
178	  private pauseShapes(): void {
179	    for (const shape of this.pauseableShapes) {
180	      shape.pause();
181	    }
182	  }
183	
184	  private resumeShapes(): void {
185	    for (const shape of this.pauseableShapes) {
186	      shape.resume();
187	    }
188	  }
189	}
190	
191	// Export singleton instance
192	export const tokenManager = new TokenManager();
