3	export function displayConflictOpLabel(op?: ConflictOp | null): string {
4	  switch (op) {
5	    case 'merge':
6	      return 'Merge';
7	    case 'cherry_pick':
8	      return 'Cherry-pick';
9	    case 'revert':
10	      return 'Revert';
11	    case 'rebase':
12	    default:
13	      return 'Rebase';
14	  }
