17	function formatConflictHeader(
18	  op: ConflictOp | null | undefined,
19	  sourceBranch: string,
20	  baseBranch?: string,
21	  repoName?: string
22	): string {
23	  const repoContext = repoName ? ` in repository '${repoName}'` : '';
24	  switch (op) {
25	    case 'merge':
26	      return `Merge conflicts while merging into '${sourceBranch}'${repoContext}.`;
27	    case 'cherry_pick':
28	      return `Cherry-pick conflicts on '${sourceBranch}'${repoContext}.`;
29	    case 'revert':
30	      return `Revert conflicts on '${sourceBranch}'${repoContext}.`;
31	    case 'rebase':
32	    default:
33	      return `Rebase conflicts while rebasing '${sourceBranch}' onto '${baseBranch ?? 'base branch'}'${repoContext}.`;
34	  }
