37	export function buildResolveConflictsInstructions(
38	  sourceBranch: string | null,
39	  baseBranch: string | undefined,
40	  conflictedFiles: string[],
41	  op?: ConflictOp | null,
42	  repoName?: string
43	): string {
44	  const source = sourceBranch || 'current attempt branch';
45	  const base = baseBranch ?? 'base branch';
46	  const filesList = conflictedFiles.slice(0, 12);
47	  const filesBlock = filesList.length
48	    ? `\n\nFiles with conflicts:\n${filesList.map((f) => `- ${f}`).join('\n')}`
49	    : '';
50	
51	  const opTitle = displayConflictOpLabel(op);
52	  const header = formatConflictHeader(op, source, base, repoName);
53	
54	  return (
55	    `${header}` +
56	    filesBlock +
57	    `\n\nPlease resolve each file carefully. When continuing, ensure the ${opTitle.toLowerCase()} does not hang (set \`GIT_EDITOR=true\` or use a non-interactive editor).`
58	  );
59	}
