14	/**
15	 * Format a date string as a relative time (e.g., "just now", "5m ago", "2h ago", "3d ago").
16	 */
17	export function formatRelativeTime(dateString: string): string {
18	  const date = new Date(dateString);
19	  const now = new Date();
20	  const diffMs = now.getTime() - date.getTime();
21	  const diffSecs = Math.floor(diffMs / 1000);
22	  const diffMins = Math.floor(diffSecs / 60);
23	  const diffHours = Math.floor(diffMins / 60);
24	  const diffDays = Math.floor(diffHours / 24);
25	
26	  if (diffSecs < 60) return 'just now';
27	  if (diffMins < 60) return `${diffMins}m ago`;
28	  if (diffHours < 24) return `${diffHours}h ago`;
29	  return `${diffDays}d ago`;
30	}
