3	/**
4	 * Extract the working directory from a dev server process's executor action.
5	 */
6	export function getDevServerWorkingDir(
7	  process: ExecutionProcess
8	): string | null {
9	  const typ = process.executor_action?.typ;
10	  if (typ && 'type' in typ && typ.type === 'ScriptRequest') {
11	    return (typ as { working_dir: string | null }).working_dir;
12	  }
13	  return null;
14	}
