16	/**
17	 * Deduplicate dev server processes by working directory, keeping the latest
18	 * process for each unique directory.
19	 */
20	export function deduplicateDevServersByWorkingDir(
21	  processes: ExecutionProcess[]
22	): ExecutionProcess[] {
23	  const byWorkingDir = new Map<string, ExecutionProcess>();
24	  for (const process of processes) {
25	    const workingDir = getDevServerWorkingDir(process) ?? 'unknown';
26	    const existing = byWorkingDir.get(workingDir);
27	    if (
28	      !existing ||
29	      new Date(process.started_at) > new Date(existing.started_at)
30	    ) {
31	      byWorkingDir.set(workingDir, process);
32	    }
33	  }
34	  return Array.from(byWorkingDir.values());
35	}
