1	import {
2	  parseDiffFromFile,
3	  type FileContents,
4	  type FileDiffMetadata,
5	  type ChangeTypes,
6	  type DiffLineAnnotation,
7	  type AnnotationSide,
8	} from '@pierre/diffs';
9	import type { Diff, DiffChangeKind } from 'shared/types';
10	import type { ReviewComment } from '@/shared/hooks/useReview';
11	import type { NormalizedGitHubComment } from '@/shared/hooks/useWorkspaceContext';
12	import { DiffSide } from '@/shared/types/diff';
13	
14	/**
15	 * Discriminated union type for comment annotations.
16	 * Allows the diff viewer to distinguish between user review comments
17	 * and GitHub PR comments.
18	 */
19	export type CommentAnnotation =
20	  | { type: 'review'; comment: ReviewComment }
21	  | { type: 'github'; comment: NormalizedGitHubComment };
22	
23	/**
24	 * Maps vibe-kanban's DiffChangeKind to pierre/diffs ChangeTypes.
25	 *
26	 * Mapping:
27	 * - 'added' → 'new'
28	 * - 'deleted' → 'deleted'
29	 * - 'modified' → 'change'
30	 * - 'renamed' → 'rename-pure' or 'rename-changed' (based on content diff)
31	 * - 'copied' → 'change'
32	 * - 'permissionChange' → 'change'
33	 */
34	function mapChangeKindToChangeType(
35	  kind: DiffChangeKind,
36	  oldContent: string | null,
37	  newContent: string | null
38	): ChangeTypes {
39	  switch (kind) {
40	    case 'added':
41	      return 'new';
42	    case 'deleted':
43	      return 'deleted';
44	    case 'modified':
45	      return 'change';
46	    case 'renamed':
47	      // Check if content differs for renamed files
48	      return oldContent === newContent ? 'rename-pure' : 'rename-changed';
49	    case 'copied':
50	      return 'change';
51	    case 'permissionChange':
52	      return 'change';
53	    default:
54	      return 'change';
55	  }
56	}
57	
58	/**
59	 * Maps DiffSide (0 = old, 1 = new) to pierre/diffs AnnotationSide.
60	 */
61	function mapSideToAnnotationSide(side: DiffSide): AnnotationSide {
62	  return side === DiffSide.Old ? 'deletions' : 'additions';
63	}
64	
65	/**
66	 * Extracts the file path from a Diff, preferring newPath for most cases.
67	 */
68	function getFilePath(diff: Diff): string {
69	  return diff.newPath ?? diff.oldPath ?? 'unknown';
70	}
71	
72	/**
73	 * Transforms a vibe-kanban Diff to pierre/diffs FileDiffMetadata.
74	 *
75	 * Uses parseDiffFromFile from @pierre/diffs to generate the diff metadata
76	 * from old and new file contents.
77	 *
78	 * @param diff - The vibe-kanban Diff object
79	 * @returns FileDiffMetadata for use with pierre/diffs components
80	 */
81	export function transformDiffToFileDiffMetadata(
82	  diff: Diff,
83	  options?: { ignoreWhitespace?: boolean }
84	): FileDiffMetadata {
85	  const filePath = getFilePath(diff);
86	
87	  // Handle contentOmitted case - create placeholder metadata
88	  if (diff.contentOmitted) {
89	    const changeType = mapChangeKindToChangeType(
90	      diff.change,
91	      diff.oldContent,
92	      diff.newContent
93	    );
94	
95	    return {
96	      name: filePath,
97	      prevName:
98	        diff.oldPath !== diff.newPath ? (diff.oldPath ?? undefined) : undefined,
99	      type: changeType,
100	      hunks: [],
101	      splitLineCount: 0,
102	      unifiedLineCount: 0,
103	    };
104	  }
105	
106	  // Prepare file contents for parseDiffFromFile
107	  const oldFile: FileContents = {
108	    name: diff.oldPath ?? filePath,
109	    contents: diff.oldContent ?? '',
110	  };
111	
112	  const newFile: FileContents = {
113	    name: filePath,
114	    contents: diff.newContent ?? '',
115	  };
116	
117	  // Use pierre/diffs parser to generate diff metadata
118	  const metadata = parseDiffFromFile(
119	    oldFile,
120	    newFile,
121	    options?.ignoreWhitespace ? { ignoreWhitespace: true } : undefined
122	  );
123	
124	  // Override the type based on our DiffChangeKind mapping
125	  // parseDiffFromFile may not correctly detect renames/copies
126	  const changeType = mapChangeKindToChangeType(
127	    diff.change,
128	    diff.oldContent,
129	    diff.newContent
130	  );
131	
132	  return {
133	    ...metadata,
134	    type: changeType,
135	    prevName:
136	      diff.oldPath !== diff.newPath ? (diff.oldPath ?? undefined) : undefined,
137	  };
138	}
139	
140	/**
141	 * Creates a unique key for a comment based on file path, line number, and side.
142	 * Used for deduplication.
143	 */
144	function createCommentKey(
145	  filePath: string,
146	  lineNumber: number,
147	  side: DiffSide
148	): string {
149	  return `${filePath}:${lineNumber}:${side}`;
150	}
151	
152	/**
153	 * Transforms review comments and GitHub comments into pierre/diffs annotations.
154	 *
155	 * Implements deduplication: if both a user review comment and a GitHub comment
156	 * exist on the same line/side, only the user review comment is included.
157	 *
158	 * @param comments - User review comments from ReviewProvider
159	 * @param githubComments - Normalized GitHub PR comments
160	 * @param filePath - The file path to filter comments for
161	 * @returns Array of DiffLineAnnotation with CommentAnnotation metadata
162	 */
163	export function transformCommentsToAnnotations(
164	  comments: ReviewComment[],
165	  githubComments: NormalizedGitHubComment[],
166	  filePath: string
167	): DiffLineAnnotation<CommentAnnotation>[] {
168	  const annotations: DiffLineAnnotation<CommentAnnotation>[] = [];
169	  const occupiedKeys = new Set<string>();
170	
171	  // First, add all user review comments (they take priority)
172	  for (const comment of comments) {
173	    if (comment.filePath !== filePath) continue;
174	
175	    const key = createCommentKey(
176	      comment.filePath,
177	      comment.lineNumber,
178	      comment.side
179	    );
180	    occupiedKeys.add(key);
181	
182	    annotations.push({
183	      side: mapSideToAnnotationSide(comment.side),
184	      lineNumber: comment.lineNumber,
185	      metadata: {
186	        type: 'review',
187	        comment,
188	      },
189	    });
190	  }
191	
192	  // Then, add GitHub comments only if no user comment exists on that line/side
193	  for (const ghComment of githubComments) {
194	    // Handle path matching - GitHub paths may not have repo prefix
195	    const pathMatches =
196	      ghComment.filePath === filePath ||
197	      filePath.endsWith('/' + ghComment.filePath);
198	
199	    if (!pathMatches) continue;
200	
201	    const key = createCommentKey(
202	      ghComment.filePath,
203	      ghComment.lineNumber,
204	      ghComment.side
205	    );
206	
207	    // Skip if user already has a comment on this line/side
208	    if (occupiedKeys.has(key)) continue;
209	
210	    annotations.push({
211	      side: mapSideToAnnotationSide(ghComment.side),
212	      lineNumber: ghComment.lineNumber,
213	      metadata: {
214	        type: 'github',
215	        comment: ghComment,
216	      },
217	    });
218	  }
219	
220	  return annotations;
221	}
