1	/**
2	 * Parse unified diff to extract addition/deletion counts.
3	 * Does not depend on any diff library.
4	 */
5	export function parseDiffStats(unifiedDiff: string): {
6	  additions: number;
7	  deletions: number;
8	} {
9	  let additions = 0;
10	  let deletions = 0;
11	  const lines = unifiedDiff.split('\n');
12	  for (const line of lines) {
13	    if (line.startsWith('+') && !line.startsWith('+++')) additions++;
14	    else if (line.startsWith('-') && !line.startsWith('---')) deletions++;
15	  }
16	  return { additions, deletions };
17	}
