79	class ErrorHandler {
80	  private lastErrorTime = 0;
81	  private lastErrorMessage = '';
82	  private consecutiveErrors = 0;
83	  private readonly baseDebounceMs = 1000;
84	  private readonly maxDebounceMs = 30000;
85	
86	  shouldReport(message: string): boolean {
87	    const now = Date.now();
88	    const debounceMs = Math.min(
89	      this.baseDebounceMs * Math.pow(2, this.consecutiveErrors),
90	      this.maxDebounceMs
91	    );
92	
93	    if (
94	      message === this.lastErrorMessage &&
95	      now - this.lastErrorTime < debounceMs
96	    ) {
97	      return false;
98	    }
99	
100	    this.lastErrorTime = now;
101	    if (message === this.lastErrorMessage) {
102	      this.consecutiveErrors += 1;
103	    } else {
104	      this.consecutiveErrors = 0;
105	      this.lastErrorMessage = message;
106	    }
107	
108	    return true;
109	  }
110	}
