296	function createErrorHandlingFetch(args: {
297	  onError: (error: SyncError) => void;
298	  onElectricUnavailable: () => void;
299	  isPaused: () => boolean;
300	}) {
301	  return async (
302	    input: RequestInfo | URL,
303	    init?: RequestInit
304	  ): Promise<Response> => {
305	    if (args.isPaused()) {
306	      throw new DOMException(
307	        'Shape request aborted: not authenticated',
308	        'AbortError'
309	      );
310	    }
311	
312	    try {
313	      return await fetch(input, init);
314	    } catch (error) {
315	      if (isTransientElectricFailure(error)) {
316	        throw error;
317	      }
318	
319	      const message = error instanceof Error ? error.message : 'Network error';
320	      args.onError({ message });
321	      args.onElectricUnavailable();
322	      throw error;
323	    }
324	  };
325	}
