327	function createElectricShapeOptions(args: {
328	  shape: ShapeDefinition<unknown>;
329	  params: Record<string, string>;
330	  reportError: (error: SyncError) => void;
331	  onElectricUnavailable: () => void;
332	}) {
333	  const authRuntime = getAuthRuntime();
334	  let isPaused = false;
335	
336	  authRuntime.registerShape({
337	    pause: () => {
338	      isPaused = true;
339	    },
340	    resume: () => {
341	      isPaused = false;
342	    },
343	  });
344	
345	  const url = buildUrl(args.shape.url, args.params);
346	
347	  return {
348	    url: `${getRemoteApiUrl()}${url}`,
349	    params: args.params,
350	    headers: {
351	      Authorization: async () => {
352	        const token = await authRuntime.getToken();
353	        if (!token) {
354	          isPaused = true;
355	          return '';
356	        }
357	        return `Bearer ${token}`;
358	      },
359	    },
360	    parser: {
361	      timestamptz: (value: string) => value,
362	    },
363	    fetchClient: createErrorHandlingFetch({
364	      onError: args.reportError,
365	      onElectricUnavailable: args.onElectricUnavailable,
366	      isPaused: () => isPaused,
367	    }),
368	    onError: (error: { status?: number; message?: string; name?: string }) => {
369	      if (isPaused) return;
370	      if (isTransientElectricShapeError(error)) return;
371	
372	      const status = error.status;
373	      const message = error.message || String(error);
374	
375	      if (status === 401) {
376	        authRuntime.triggerRefresh().catch(() => {
377	          args.reportError({ status, message });
378	        });
379	        return;
380	      }
381	
382	      args.reportError({ status, message });
383	
384	      if (status === undefined || status >= 500) {
385	        args.onElectricUnavailable();
386	      }
387	    },
388	  };
389	}
