438	function createFallbackSync(args: {
439	  sourceKey: string;
440	  shape: ShapeDefinition<unknown>;
441	  params: Record<string, string>;
442	  reportError: (error: SyncError) => void;
443	}) {
444	  return (syncParams: SyncParams): SyncResult => {
445	    const runtime = getOrCreateSourceRuntime(args.sourceKey);
446	    runtime.mode = 'fallback';
447	    runtime.fallbackLocked = true;
448	
449	    let isCleanedUp = false;
450	    let refreshPromise: Promise<void> | null = null;
451	
452	    const refreshNow = async () => {
453	      if (refreshPromise) {
454	        return refreshPromise;
455	      }
456	
457	      refreshPromise = (async () => {
458	        try {
459	          const response = await makeRequest(
460	            buildFallbackRequestPath(args.shape.fallbackUrl, args.params),
461	            { method: 'GET', cache: 'no-store' }
462	          );
463	
464	          if (!response.ok) {
465	            const message = await parseResponseError(
466	              response,
467	              `Failed to fetch fallback ${args.shape.table}`
468	            );
469	            throw new Error(message);
470	          }
471	
472	          const payload = (await response.json()) as unknown;
473	          const rows = extractFallbackRows(payload, args.shape.table);
474	          fallbackSnapshotCache.set(args.sourceKey, rows);
475	
476	          if (!isCleanedUp) {
477	            applySnapshot(syncParams, rows);
478	          }
479	        } catch (error) {
480	          if (isAbortError(error)) return;
481	
482	          const message =
483	            error instanceof Error ? error.message : 'Fallback fetch failed';
484	          args.reportError({ message });
485	
486	          if (!isCleanedUp && !syncParams.collection.isReady()) {
487	            syncParams.markReady();
488	          }
489	        } finally {
490	          refreshPromise = null;
491	        }
492	      })();
493	
494	      return refreshPromise;
495	    };
496	
497	    const unregisterRefresher = registerFallbackRefresher(
498	      args.sourceKey,
499	      refreshNow
500	    );
501	
502	    const cachedRows = fallbackSnapshotCache.get(args.sourceKey);
503	    if (cachedRows) {
504	      applySnapshot(syncParams, cachedRows);
505	    }
506	
507	    void refreshNow();
508	
509	    const intervalId = globalThis.setInterval(() => {
510	      void refreshNow();
511	    }, FALLBACK_REFRESH_INTERVAL_MS);
512	
513	    return {
514	      cleanup: () => {
515	        isCleanedUp = true;
516	        globalThis.clearInterval(intervalId);
517	        unregisterRefresher();
518	      },
519	      loadSubset: () => true,
520	    };
521	  };
522	}
