524	function createHybridSync(args: {
525	  sourceKey: string;
526	  shape: ShapeDefinition<unknown>;
527	  params: Record<string, string>;
528	  reportError: (error: SyncError) => void;
529	  electricSync: SyncConfigLike['sync'];
530	}) {
