539	    const runtime = getOrCreateSourceRuntime(args.sourceKey);
540	    if (runtime.fallbackLocked) {
541	      return fallbackSync(syncParams);
542	    }
543	
544	    runtime.mode = 'electric';
545	
546	    let isCleanedUp = false;
547	    let usingFallback = false;
548	    let timeoutId: ReturnType<typeof globalThis.setTimeout> | null = null;
549	
550	    let activeSync = normalizeSyncResult(args.electricSync(syncParams));
551	
552	    const switchToFallback = () => {
553	      if (isCleanedUp || usingFallback) return;
554	      usingFallback = true;
555	
556	      activeSync.cleanup?.();
557	      activeSync = normalizeSyncResult(fallbackSync(syncParams));
558	    };
559	
560	    const unregisterSwitcher = registerFallbackSwitcher(
561	      args.sourceKey,
562	      switchToFallback
563	    );
564	
565	    const scheduleReadyTimeout = () => {
566	      timeoutId = globalThis.setTimeout(() => {
567	        if (isCleanedUp || usingFallback || syncParams.collection.isReady()) {
568	          return;
569	        }
570	
571	        if (!isPageVisible()) {
572	          scheduleReadyTimeout();
573	          return;
574	        }
575	
576	        args.reportError({
577	          message: `Electric sync timed out after ${ELECTRIC_READY_TIMEOUT_MS}ms, switching to fallback`,
578	        });
579	        lockSourceToFallback(args.sourceKey);
580	      }, ELECTRIC_READY_TIMEOUT_MS);
581	    };
582	
583	    scheduleReadyTimeout();
584	
585	    syncParams.collection.onFirstReady(() => {
586	      if (!usingFallback) {
587	        if (timeoutId) {
588	          globalThis.clearTimeout(timeoutId);
589	        }
590	      }
591	    });
592	
593	    return {
594	      cleanup: () => {
595	        isCleanedUp = true;
596	        if (timeoutId) {
597	          globalThis.clearTimeout(timeoutId);
598	        }
599	        unregisterSwitcher();
600	        activeSync.cleanup?.();
601	      },
602	      loadSubset: (options: unknown) =>
603	        activeSync.loadSubset ? activeSync.loadSubset(options) : true,
604	      unloadSubset: (options: unknown) => {
605	        activeSync.unloadSubset?.(options);
606	      },
607	    };
608	  };
609	}
