726	
727	    onDelete: async ({
728	      transaction,
729	    }: MutationFnParams): Promise<{ txid: number[] } | void> => {
730	      const txids = await Promise.all(
731	        transaction.mutations.map(async (mutationItem) => {
732	          const response = await makeRequest(
733	            `${mutation.url}/${mutationItem.key}`,
734	            {
735	              method: 'DELETE',
736	            }
737	          );
738	
739	          if (!response.ok) {
740	            const message = await parseResponseError(
741	              response,
742	              `Failed to delete ${mutation.name}`
743	            );
744	            throw new Error(message);
745	          }
746	
747	          const result = (await response.json()) as { txid: number };
748	          return result.txid;
749	        })
750	      );
751	
752	      maybeRefreshFallbackAfterMutation(sourceKey);
753	
754	      if (isSourceFallbackLocked(sourceKey)) {
755	        return;
756	      }
757	
758	      return { txid: txids };
759	    },
760	  };
761	}
