763	export function createShapeCollection<TRow extends ElectricRow>(
764	  shape: ShapeDefinition<TRow>,
765	  params: Record<string, string>,
766	  config?: CollectionConfig,
767	  mutation?: MutationDefinition<unknown, unknown, unknown>
768	) {
769	  const hasMutations = Boolean(mutation);
770	  const collectionId = buildCollectionId(shape.table, params, hasMutations);
771	  const sourceKey = buildSourceKey(shape.table, params);
772	
773	  const cached = collectionCache.get(collectionId);
774	  if (cached) {
775	    return cached as typeof cached & { __rowType?: TRow };
776	  }
777	
778	  const reportError = createErrorReporter(config);
779	  const onElectricUnavailable = () => lockSourceToFallback(sourceKey);
780	
781	  const shapeOptions = createElectricShapeOptions({
782	    shape,
783	    params,
784	    reportError,
785	    onElectricUnavailable,
786	  });
787	
788	  const mutationHandlers = mutation
789	    ? buildMutationHandlers(mutation, sourceKey)
790	    : {};
791	
792	  const electricOptions = electricCollectionOptions({
793	    id: collectionId,
794	    shapeOptions: shapeOptions as never,
795	    getKey: (item: ElectricRow) => getRowKey(item),
796	    gcTime: DEFAULT_GC_TIME_MS,
797	    ...mutationHandlers,
798	  } as never);
799	
800	  const electricSyncConfig = electricOptions.sync as unknown as SyncConfigLike;
801	
802	  const collectionOptions = {
803	    ...electricOptions,
804	    sync: {
805	      ...electricSyncConfig,
806	      sync: createHybridSync({
807	        sourceKey,
808	        shape,
809	        params,
810	        reportError,
811	        electricSync: electricSyncConfig.sync,
812	      }),
813	    },
814	  };
815	
816	  const collection = createCollection(
817	    collectionOptions as never
818	  ) as unknown as ReturnType<typeof createCollection> & { __rowType?: TRow };
819	
820	  collectionCache.set(collectionId, collection);
821	  return collection;
822	}
