67	/**
68	 * Extract full ExecutorConfig from an ExecutorAction chain.
69	 * Traverses the action chain to find the first coding agent request.
70	 */
71	export function executorConfigFromAction(
72	  action: ExecutorAction | null
73	): ExecutorConfig | null {
74	  let curr: ExecutorAction | null = action;
75	  while (curr) {
76	    const typ = curr.typ;
77	    switch (typ.type) {
78	      case 'CodingAgentInitialRequest':
79	      case 'CodingAgentFollowUpRequest':
80	      case 'ReviewRequest':
81	        return typ.executor_config;
82	      case 'ScriptRequest':
83	      default:
84	        curr = curr.next_action;
85	        continue;
86	    }
87	  }
88	  return null;
