1	import type { Diff } from 'shared/types';
2	import type { TreeNode } from '@/shared/types/fileTree';
3	
4	/**
5	 * Transforms flat Diff[] into hierarchical TreeNode[]
6	 */
7	export function buildFileTree(diffs: Diff[]): TreeNode[] {
8	  const rootMap = new Map<string, TreeNode>();
9	
10	  for (const diff of diffs) {
11	    // Use newPath for most changes, oldPath for deletions
12	    const filePath = diff.newPath ?? diff.oldPath;
13	    if (!filePath) continue;
14	
15	    const parts = filePath.split('/');
16	    let currentMap = rootMap;
17	
18	    for (let i = 0; i < parts.length; i++) {
19	      const part = parts[i];
20	      const isFile = i === parts.length - 1;
21	      const currentPath = parts.slice(0, i + 1).join('/');
22	
23	      if (!currentMap.has(part)) {
24	        const node: TreeNode = {
25	          id: currentPath,
26	          name: part,
27	          path: currentPath,
28	          type: isFile ? 'file' : 'folder',
29	          children: isFile ? undefined : [],
30	        };
31	
32	        if (isFile) {
33	          node.diff = diff;
34	          node.changeKind = diff.change;
35	          node.additions = diff.additions;
36	          node.deletions = diff.deletions;
37	        }
38	
39	        currentMap.set(part, node);
40	      }
41	
42	      const node = currentMap.get(part)!;
43	
44	      if (!isFile && node.children) {
45	        // Build map for next level from existing children
46	        const childMap = new Map<string, TreeNode>();
47	        for (const child of node.children) {
48	          childMap.set(child.name, child);
49	        }
50	
51	        // Process remaining parts, then sync back to children array
52	        if (i < parts.length - 1) {
53	          const nextPart = parts[i + 1];
54	          const nextPath = parts.slice(0, i + 2).join('/');
55	          const nextIsFile = i + 1 === parts.length - 1;
56	
57	          if (!childMap.has(nextPart)) {
58	            const nextNode: TreeNode = {
59	              id: nextPath,
60	              name: nextPart,
61	              path: nextPath,
62	              type: nextIsFile ? 'file' : 'folder',
63	              children: nextIsFile ? undefined : [],
64	            };
65	
66	            if (nextIsFile) {
67	              nextNode.diff = diff;
68	              nextNode.changeKind = diff.change;
69	              nextNode.additions = diff.additions;
70	              nextNode.deletions = diff.deletions;
71	            }
72	
73	            childMap.set(nextPart, nextNode);
74	            node.children.push(nextNode);
75	          }
76	
77	          currentMap = childMap;
78	        }
79	      }
80	    }
81	  }
82	
83	  return sortTreeNodes(Array.from(rootMap.values()));
84	}
85	
86	/**
87	 * Sort nodes: folders first, then alphabetically
88	 */
89	function sortTreeNodes(nodes: TreeNode[]): TreeNode[] {
90	  return nodes
91	    .map((node) => ({
92	      ...node,
93	      children: node.children ? sortTreeNodes(node.children) : undefined,
94	    }))
95	    .sort((a, b) => {
96	      // Folders before files
97	      if (a.type !== b.type) {
98	        return a.type === 'folder' ? -1 : 1;
99	      }
100	      // Alphabetical within same type
101	      return a.name.localeCompare(b.name);
102	    });
103	}
104	
105	/**
106	 * Filter tree based on search query only
107	 */
108	export function filterFileTree(
109	  nodes: TreeNode[],
110	  searchQuery: string
111	): TreeNode[] {
112	  if (!searchQuery) {
113	    return nodes;
114	  }
115	
116	  const query = searchQuery.toLowerCase();
117	
118	  function filterNode(node: TreeNode): TreeNode | null {
119	    // For folders, recursively filter children
120	    if (node.type === 'folder' && node.children) {
121	      const filteredChildren = node.children
122	        .map(filterNode)
123	        .filter((n): n is TreeNode => n !== null);
124	
125	      if (filteredChildren.length === 0) {
126	        return null;
127	      }
128	
129	      return { ...node, children: filteredChildren };
130	    }
131	
132	    // For files, check search query
133	    if (node.type === 'file') {
134	      if (node.path.toLowerCase().includes(query)) {
135	        return node;
136	      }
137	    }
138	
139	    return null;
140	  }
141	
142	  return nodes.map(filterNode).filter((n): n is TreeNode => n !== null);
143	}
144	
145	/**
146	 * Get all folder paths that should be expanded to show matching files
147	 */
148	export function getExpandedPathsForSearch(
149	  nodes: TreeNode[],
150	  searchQuery: string
151	): Set<string> {
152	  const paths = new Set<string>();
153	  const query = searchQuery.toLowerCase();
154	
155	  function traverse(node: TreeNode, parentPaths: string[]) {
156	    if (node.type === 'file' && node.path.toLowerCase().includes(query)) {
157	      // Add all parent folder paths
158	      parentPaths.forEach((p) => paths.add(p));
159	    }
160	
161	    if (node.children) {
162	      const currentPaths = [...parentPaths, node.path];
163	      node.children.forEach((child) => traverse(child, currentPaths));
164	    }
165	  }
166	
167	  nodes.forEach((node) => traverse(node, []));
168	  return paths;
169	}
170	
171	/**
172	 * Get all folder paths in the tree
173	 */
174	export function getAllFolderPaths(nodes: TreeNode[]): string[] {
175	  const paths: string[] = [];
176	
177	  function traverse(node: TreeNode) {
178	    if (node.type === 'folder') {
179	      paths.push(node.path);
180	      node.children?.forEach(traverse);
181	    }
182	  }
183	
184	  nodes.forEach(traverse);
185	  return paths;
186	}
187	
188	/**
189	 * Sort diffs to match FileTree ordering: folders before files at each level,
190	 * then alphabetically within each group
191	 */
192	export function sortDiffs(diffs: Diff[]): Diff[] {
193	  return [...diffs].sort((a, b) => {
194	    const pathA = a.newPath || a.oldPath || '';
195	    const pathB = b.newPath || b.oldPath || '';
196	
197	    const partsA = pathA.split('/');
198	    const partsB = pathB.split('/');
199	
200	    const minLength = Math.min(partsA.length, partsB.length);
201	
202	    for (let i = 0; i < minLength; i++) {
203	      const isLastA = i === partsA.length - 1;
204	      const isLastB = i === partsB.length - 1;
205	
206	      // If one is a file (last segment) and other is a folder (not last), folder comes first
207	      if (isLastA !== isLastB) {
208	        return isLastA ? 1 : -1;
209	      }
210	
211	      // Same type at this level, compare alphabetically
212	      const cmp = partsA[i].localeCompare(partsB[i]);
213	      if (cmp !== 0) return cmp;
214	    }
215	
216	    // Shorter path (folder) comes before longer path (nested file)
217	    return partsA.length - partsB.length;
218	  });
219	}
