7	
8	const FIRST_PROJECT_LOOKUP_TIMEOUT_MS = 3000;
9	
10	function getFirstOrganization(
11	  organizations: OrganizationWithRole[]
12	): OrganizationWithRole | null {
13	  if (organizations.length === 0) {
14	    return null;
15	  }
16	
17	  return organizations[0];
18	}
19	
20	async function getProjectsInOrganization(
21	  organizationId: string
22	): Promise<Project[] | null> {
23	  const collection = createShapeCollection(PROJECTS_SHAPE, {
24	    organization_id: organizationId,
25	  });
26	
27	  const getCollectionProjects = () =>
28	    collection.toArray as unknown as Project[];
29	
30	  if (collection.isReady()) {
31	    return getCollectionProjects();
32	  }
33	
34	  return new Promise<Project[] | null>((resolve) => {
35	    let settled = false;
36	    let timeoutId: number | undefined;
37	    let subscription: { unsubscribe: () => void } | undefined;
38	
39	    const settle = (projects: Project[] | null) => {
40	      if (settled) return;
41	      settled = true;
42	
43	      if (timeoutId !== undefined) {
44	        window.clearTimeout(timeoutId);
45	        timeoutId = undefined;
46	      }
47	      if (subscription) {
48	        subscription.unsubscribe();
49	        subscription = undefined;
50	      }
51	
52	      resolve(projects);
53	    };
54	
55	    const tryResolve = () => {
56	      if (!collection.isReady()) {
57	        return;
58	      }
59	
60	      settle(getCollectionProjects());
61	    };
62	
63	    subscription = collection.subscribeChanges(tryResolve, {
64	      includeInitialState: true,
65	    });
66	
67	    timeoutId = window.setTimeout(() => {
68	      settle(null);
69	    }, FIRST_PROJECT_LOOKUP_TIMEOUT_MS);
70	
71	    tryResolve();
72	  });
73	}
