75	export async function getFirstProjectDestination(
76	  setSelectedOrgId: (orgId: string | null) => void,
77	  savedOrgId?: string | null,
78	  savedProjectId?: string | null
79	): Promise<AppDestination | null> {
80	  try {
81	    const organizationsResponse = await organizationsApi.getUserOrganizations();
82	    const organizations = organizationsResponse.organizations ?? [];
83	
84	    // Prefer saved org if it still exists, otherwise fall back to first org
85	    const savedOrg = savedOrgId
86	      ? organizations.find((org) => org.id === savedOrgId)
87	      : null;
88	    const resolvedOrg = savedOrg ?? getFirstOrganization(organizations);
89	
90	    if (!resolvedOrg) {
91	      return null;
92	    }
93	
94	    setSelectedOrgId(resolvedOrg.id);
95	
96	    const projects = await getProjectsInOrganization(resolvedOrg.id);
97	
98	    // If we have a saved project in the same saved org, use it if still valid
99	    if (savedProjectId && savedOrg && projects) {
100	      if (projects.some((p) => p.id === savedProjectId)) {
101	        return { kind: 'project', projectId: savedProjectId };
102	      }
103	    }
104	
105	    // Fall back to first project by sort order
106	    const firstProject = projects ? getFirstProjectByOrder(projects) : null;
107	    if (!firstProject) {
108	      return null;
109	    }
110	
111	    return { kind: 'project', projectId: firstProject.id };
112	  } catch (error) {
113	    console.error('Failed to resolve first project destination:', error);
114	    return null;
115	  }
116	}
