1	import { createContext, type Context } from 'react';
2	
3	/**
4	 * Creates a React context that preserves its identity across Vite HMR updates.
5	 *
6	 * During HMR, module re-execution creates a new context object via createContext(),
7	 * but already-mounted providers still hold the old one. Consumers then read from
8	 * the new context, find no matching provider, and get the default value (typically
9	 * null/undefined), which causes "must be used within Provider" errors.
10	 *
11	 * This helper stashes the context in import.meta.hot.data so the same object is
12	 * reused across HMR re-executions of the module.
13	 *
14	 * @param key - A unique string key to identify this context in HMR data
15	 * @param defaultValue - The default context value (same as createContext's argument)
16	 */
17	export function createHmrContext<T>(key: string, defaultValue: T): Context<T> {
18	  const existing = import.meta.hot?.data?.[key] as Context<T> | undefined;
19	  const ctx = existing ?? createContext<T>(defaultValue);
20	  if (import.meta.hot) {
21	    import.meta.hot.data[key] = ctx;
22	  }
23	  return ctx;
24	}
