1	export interface LocalApiTransport {
2	  request: (pathOrUrl: string, init?: RequestInit) => Promise<Response>;
3	  openWebSocket: (pathOrUrl: string) => Promise<WebSocket> | WebSocket;
4	}
5	
6	function isAbsoluteUrl(pathOrUrl: string): boolean {
7	  return /^https?:\/\//i.test(pathOrUrl) || /^wss?:\/\//i.test(pathOrUrl);
8	}
9	
10	function toAbsoluteWsUrl(pathOrUrl: string): string {
11	  if (/^wss?:\/\//i.test(pathOrUrl)) {
12	    return pathOrUrl;
13	  }
14	
15	  if (/^https?:\/\//i.test(pathOrUrl)) {
16	    return pathOrUrl.replace(/^http/i, 'ws');
17	  }
18	
19	  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
20	  const normalizedPath = pathOrUrl.startsWith('/')
21	    ? pathOrUrl
22	    : `/${pathOrUrl}`;
23	  return `${protocol}//${window.location.host}${normalizedPath}`;
24	}
25	
26	const defaultTransport: LocalApiTransport = {
27	  request: (pathOrUrl, init = {}) => fetch(pathOrUrl, init),
28	  openWebSocket: (pathOrUrl) => new WebSocket(toAbsoluteWsUrl(pathOrUrl)),
29	};
30	
31	let transport: LocalApiTransport = defaultTransport;
32	
33	export function setLocalApiTransport(nextTransport: LocalApiTransport | null) {
34	  transport = nextTransport ?? defaultTransport;
35	}
36	
37	export async function makeLocalApiRequest(
38	  pathOrUrl: string,
39	  init: RequestInit = {}
40	): Promise<Response> {
41	  return transport.request(pathOrUrl, init);
42	}
43	
44	export async function openLocalApiWebSocket(
45	  pathOrUrl: string
46	): Promise<WebSocket> {
47	  return transport.openWebSocket(pathOrUrl);
48	}
