50	export function isLocalApiPath(pathOrUrl: string): boolean {
51	  if (isAbsoluteUrl(pathOrUrl)) {
52	    const url = new URL(pathOrUrl);
53	    return url.pathname.startsWith('/api/');
54	  }
55	
56	  const normalizedPath = pathOrUrl.startsWith('/')
57	    ? pathOrUrl
58	    : `/${pathOrUrl}`;
59	  return normalizedPath.startsWith('/api/');
60	}
61	
62	export function toPathAndQuery(pathOrUrl: string): string {
63	  if (isAbsoluteUrl(pathOrUrl)) {
64	    const url = new URL(pathOrUrl);
65	    return `${url.pathname}${url.search}`;
66	  }
67	
68	  return pathOrUrl.startsWith('/') ? pathOrUrl : `/${pathOrUrl}`;
69	}
