5	function isJsonObject(v: unknown): v is JsonObject {
6	  return typeof v === 'object' && v !== null && !Array.isArray(v);
7	}
8	
9	export class McpConfigStrategyGeneral {
10	  static createFullConfig(cfg: McpConfig): JsonObject {
11	    const cloned: JsonValue = JSON.parse(JSON.stringify(cfg.template ?? {}));
12	    const fullConfig: JsonObject = isJsonObject(cloned) ? cloned : {};
13	    let current: JsonObject = fullConfig;
14	
15	    for (let i = 0; i < cfg.servers_path.length - 1; i++) {
16	      const key = cfg.servers_path[i];
17	      const next = isJsonObject(current[key])
18	        ? (current[key] as JsonObject)
19	        : undefined;
20	      if (!next) current[key] = {};
21	      current = current[key] as JsonObject;
22	    }
23	
24	    if (cfg.servers_path.length > 0) {
25	      const lastKey = cfg.servers_path[cfg.servers_path.length - 1];
26	      current[lastKey] = cfg.servers;
27	    }
28	    return fullConfig;
29	  }
30	  static validateFullConfig(
31	    mcp_config: McpConfig,
32	    full_config: JsonValue
33	  ): void {
34	    let current: JsonValue = full_config;
35	    for (const key of mcp_config.servers_path) {
36	      if (!isJsonObject(current)) {
37	        throw new Error(
38	          `Expected object at path: ${mcp_config.servers_path.join('.')}`
39	        );
40	      }
41	      current = current[key];
42	      if (current === undefined) {
43	        throw new Error(
44	          `Missing required field at path: ${mcp_config.servers_path.join('.')}`
45	        );
46	      }
47	    }
48	    if (!isJsonObject(current)) {
49	      throw new Error('Servers configuration must be an object');
50	    }
51	  }
52	  static extractServersForApi(
53	    mcp_config: McpConfig,
54	    full_config: JsonValue
55	  ): JsonObject {
56	    let current: JsonValue = full_config;
57	    for (const key of mcp_config.servers_path) {
58	      if (!isJsonObject(current)) {
59	        throw new Error(
60	          `Expected object at path: ${mcp_config.servers_path.join('.')}`
61	        );
62	      }
63	      current = current[key];
64	      if (current === undefined) {
65	        throw new Error(
66	          `Missing required field at path: ${mcp_config.servers_path.join('.')}`
67	        );
68	      }
69	    }
70	    if (!isJsonObject(current)) {
71	      throw new Error('Servers configuration must be an object');
72	    }
73	    return current;
74	  }
75	
76	  static addPreconfiguredToConfig(
77	    mcp_config: McpConfig,
78	    existingConfig: JsonValue,
79	    serverKey: string
80	  ): JsonObject {
81	    const preconfVal = mcp_config.preconfigured;
82	    if (!isJsonObject(preconfVal) || !(serverKey in preconfVal)) {
83	      throw new Error(`Unknown preconfigured server '${serverKey}'`);
84	    }
85	
86	    const updatedVal: JsonValue = JSON.parse(
87	      JSON.stringify(existingConfig ?? {})
88	    );
89	    const updated: JsonObject = isJsonObject(updatedVal) ? updatedVal : {};
90	    let current: JsonObject = updated;
91	
92	    for (let i = 0; i < mcp_config.servers_path.length - 1; i++) {
93	      const key = mcp_config.servers_path[i];
94	      const next = isJsonObject(current[key])
95	        ? (current[key] as JsonObject)
96	        : undefined;
97	      if (!next) current[key] = {};
98	      current = current[key] as JsonObject;
99	    }
100	
101	    if (mcp_config.servers_path.length === 0) {
102	      current[serverKey] = preconfVal[serverKey];
103	      return updated;
104	    }
105	
106	    const lastKey = mcp_config.servers_path[mcp_config.servers_path.length - 1];
107	    if (!isJsonObject(current[lastKey])) current[lastKey] = {};
108	    (current[lastKey] as JsonObject)[serverKey] = preconfVal[serverKey];
109	
110	    return updated;
111	  }
112	}
