45	export function escapeAttributeValue(value: string): string {
46	  if (typeof CSS !== 'undefined' && typeof CSS.escape === 'function') {
47	    return CSS.escape(value);
48	  }
49	  return value.replace(/["\\]/g, '\\$&');
