52	export function parseModelId(
53	  value?: string | null,
54	  hasProviders?: boolean
55	): {
56	  providerId: string | null;
57	  modelId: string | null;
58	} {
59	  if (!value) return { providerId: null, modelId: null };
60	  if (!hasProviders) return { providerId: null, modelId: value };
61	  const slashIdx = value.indexOf('/');
62	  if (slashIdx === -1) return { providerId: null, modelId: value };
63	  return {
64	    providerId: value.substring(0, slashIdx),
65	    modelId: value.substring(slashIdx + 1),
66	  };
67	}
