69	export function appendPresetModel(
70	  config: ModelSelectorConfig | null,
71	  presetModel: string | null | undefined
72	): ModelSelectorConfig | null {
73	  if (!config || !presetModel) return config;
74	  const hasProviders = config.providers.length > 0;
75	  const { providerId, modelId } = parseModelId(presetModel, hasProviders);
76	  if (!modelId) return config;
77	
78	  const exists = config.models.some(
79	    (m) =>
80	      m.id.toLowerCase() === modelId.toLowerCase() &&
81	      (!providerId || m.provider_id?.toLowerCase() === providerId.toLowerCase())
82	  );
83	  if (exists) return config;
84	
85	  return {
86	    ...config,
87	    models: [
88	      {
89	        id: modelId,
90	        name: modelId,
91	        provider_id: providerId,
92	        reasoning_options: [],
93	      },
94	      ...config.models,
95	    ],
96	  };
97	}
