99	export function resolveDefaultModelId(
100	  models: ModelInfo[],
101	  providerId: string | null,
102	  defaultModel: string | null | undefined,
103	  hasProviders?: boolean
104	): string | null {
105	  if (models.length === 0) return null;
106	  const scoped = providerId
107	    ? models.filter((model) => model.provider_id === providerId)
108	    : models;
109	  if (scoped.length === 0) return null;
110	
111	  const { providerId: defaultProvider, modelId: defaultId } = parseModelId(
112	    defaultModel,
113	    hasProviders
114	  );
115	  if (
116	    defaultId &&
117	    (!providerId || !defaultProvider || providerId === defaultProvider)
118	  ) {
119	    const match = scoped.find((model) => model.id === defaultId);
120	    if (match) return match.id;
121	  }
122	
123	  if (!defaultModel) return null;
124	
125	  return scoped[0]?.id ?? null;
126	}
