128	export function isModelAvailable(
129	  config: ModelSelectorConfig,
130	  providerId: string,
131	  modelId: string
132	): boolean {
133	  const providerLower = providerId.toLowerCase();
134	  const modelLower = modelId.toLowerCase();
135	  return config.models.some(
136	    (model) =>
137	      model.id.toLowerCase() === modelLower &&
138	      model.provider_id?.toLowerCase() === providerLower
139	  );
140	}
