27	function getMemberLabel(member?: OrganizationMemberWithProfile): string | null {
28	  if (!member) return null;
29	
30	  const fullName = [member.first_name, member.last_name]
31	    .filter((value): value is string => Boolean(value && value.trim()))
32	    .join(' ');
33	
34	  if (fullName) return fullName;
35	  if (member.username?.trim()) return member.username;
36	
37	  return null;
38	}
