49	function getActorSegments(group: GroupedNotification): MessageSegment[] {
50	  const actorId = getPayload(group.latest).actor_user_id;
51	  return actorId ? [user(actorId)] : [text('Someone')];
52	}
53	
54	function getIssueSegments(group: GroupedNotification): MessageSegment[] {
55	  const payload = getPayload(group.latest);
56	  if (payload.issue_simple_id) {
57	    return [issue(payload.issue_simple_id)];
58	  }
