60	  return [emphasis(payload.issue_title ?? 'an issue')];
61	}
62	
63	function formatCountLabel(
64	  count: number,
65	  singular: string,
66	  plural = `${singular}s`
67	): string {
68	  return `${count} ${count === 1 ? singular : plural}`;
69	}
