71	export function getGroupedNotificationSegments(
72	  group: GroupedNotification
73	): MessageSegment[] {
74	  const payload = getPayload(group.latest);
75	  const actor = getActorSegments(group);
76	  const issueSegments = getIssueSegments(group);
77	
78	  if (group.kind !== 'single' && group.notificationCount > 1) {
79	    switch (group.kind) {
80	      case 'issue_changes':
81	        return [
82	          ...actor,
83	          text(' changed '),
84	          emphasis(formatCountLabel(group.issueChangeCount, 'field')),
85	          text(' on '),
86	          ...issueSegments,
87	        ];
88	      case 'comments':
89	        return [
90	          ...actor,
91	          text(' left '),
92	          emphasis(formatCountLabel(group.notificationCount, 'comment')),
93	          text(' on '),
94	          ...issueSegments,
95	        ];
96	      case 'status_changes':
97	        return [...actor, text(' changed status on '), ...issueSegments];
98	      case 'reactions':
99	        return [
100	          ...actor,
101	          text(' reacted '),
102	          emphasis(formatCountLabel(group.notificationCount, 'time')),
103	          text(' on '),
104	          ...issueSegments,
105	        ];
106	      case 'issue_deleted':
107	        return [
108	          ...actor,
109	          text(' deleted '),
110	          emphasis(formatCountLabel(group.notificationCount, 'issue')),
111	        ];
112	    }
113	  }
114	
115	  switch (group.latest.notification_type) {
116	    case 'issue_title_changed': {
117	      const newTitle = payload.new_title;
118	      if (newTitle) {
119	        return [
120	          ...actor,
121	          text(' changed the title of '),
122	          ...issueSegments,
123	          text(' to '),
124	          emphasis(newTitle),
125	        ];
126	      }
127	      return [...actor, text(' changed the title of '), ...issueSegments];
128	    }
129	    case 'issue_assignee_changed': {
130	      const assigneeId = payload.assignee_user_id;
131	      const assignee = assigneeId ? [user(assigneeId)] : [text('Someone')];
132	      return [
133	        ...assignee,
134	        text(' was assigned to '),
135	        ...issueSegments,
136	        text(' by '),
137	        ...actor,
138	      ];
139	    }
140	    case 'issue_unassigned':
141	      return [...actor, text(' unassigned you from '), ...issueSegments];
142	    case 'issue_description_changed':
143	      return [...actor, text(' changed the description on '), ...issueSegments];
144	    case 'issue_priority_changed': {
145	      const oldPriority = formatPriority(payload.old_priority);
146	      const newPriority = formatPriority(payload.new_priority);
147	
148	      if (oldPriority && newPriority) {
149	        return [
150	          ...actor,
151	          text(' changed the priority of '),
152	          ...issueSegments,
153	          text(' from '),
154	          emphasis(oldPriority),
155	          text(' to '),
156	          emphasis(newPriority),
157	        ];
158	      }
159	
160	      if (newPriority) {
161	        return [
162	          ...actor,
163	          text(' changed the priority of '),
164	          ...issueSegments,
165	          text(' to '),
166	          emphasis(newPriority),
167	        ];
168	      }
169	
170	      return [...actor, text(' cleared the priority of '), ...issueSegments];
171	    }
172	    case 'issue_comment_added':
173	      return [...actor, text(' commented on '), ...issueSegments];
174	    case 'issue_comment_reaction': {
175	      const emoji = payload.emoji;
176	      if (emoji) {
177	        return [
178	          ...actor,
179	          text(' reacted '),
180	          emphasis(emoji),
181	          text(' to your comment on '),
182	          ...issueSegments,
183	        ];
184	      }
185	      return [...actor, text(' reacted to your comment on '), ...issueSegments];
186	    }
187	    case 'issue_status_changed': {
188	      const oldStatusName = payload.old_status_name;
189	      const newStatusName = payload.new_status_name;
190	
191	      if (oldStatusName && newStatusName) {
192	        return [
193	          ...actor,
194	          text(' changed status of '),
195	          ...issueSegments,
196	          text(' from '),
197	          emphasis(oldStatusName),
198	          text(' to '),
199	          emphasis(newStatusName),
200	        ];
201	      }
202	
203	      return [...actor, text(' changed status of '), ...issueSegments];
204	    }
205	    case 'issue_deleted':
206	      return [...actor, text(' deleted '), ...issueSegments];
207	    default:
208	      return [text('New notification')];
209	  }
210	}
