194	function shouldStartNewGroup(
195	  group: GroupAccumulator,
196	  notification: Notification
197	): boolean {
198	  return (
199	    getCreatedAtTimestamp(group.latest) - getCreatedAtTimestamp(notification) >
200	    GROUP_WINDOW_MS
201	  );
202	}
203	
204	function finalizeGroup(group: GroupAccumulator): GroupedNotification {
205	  return buildGroupedNotification(
206	    group.id,
207	    group.kind,
208	    group.latest,
209	    group.notifications,
210	    group.kind === 'issue_changes'
211	      ? Math.max(group.issueChangeFields.size, 1)
212	      : 0
213	  );
214	}
215	
216	function addNotificationToGroup(
217	  group: GroupAccumulator,
218	  notification: Notification,
219	  meta: NotificationGroupingMeta
220	) {
221	  group.notifications.push(notification);
222	
223	  if (meta.issueChangeField) {
224	    group.issueChangeFields.add(meta.issueChangeField);
225	  }
226	}
227	
228	export function groupNotifications(
229	  notifications: Notification[]
230	): GroupedNotification[] {
231	  const sorted = [...notifications].sort(
232	    (a, b) => getCreatedAtTimestamp(b) - getCreatedAtTimestamp(a)
233	  );
234	  const groups: GroupedNotification[] = [];
235	  const groupsByKey = new Map<string, ActiveGroup>();
236	
237	  for (const notification of sorted) {
238	    const meta = getGroupingMeta(notification);
239	    if (!meta) {
240	      groups.push(buildSingleGroupedNotification(notification));
241	      continue;
242	    }
243	
244	    const groupKey = getGroupKey(notification, meta);
245	    if (!groupKey) {
246	      groups.push(buildSingleGroupedNotification(notification));
247	      continue;
248	    }
249	
250	    const activeGroup = groupsByKey.get(groupKey);
251	    if (!activeGroup || shouldStartNewGroup(activeGroup.group, notification)) {
252	      const nextGroup = createAccumulator(notification, groupKey, meta);
253	      const index = groups.length;
254	      groups.push(finalizeGroup(nextGroup));
255	      groupsByKey.set(groupKey, { index, group: nextGroup });
256	      continue;
257	    }
258	
259	    addNotificationToGroup(activeGroup.group, notification, meta);
260	    groups[activeGroup.index] = finalizeGroup(activeGroup.group);
261	  }
262	
263	  return groups;
264	}
