3	export function compareProjectsByOrder(a: Project, b: Project): number {
4	  const bySortOrder = a.sort_order - b.sort_order;
5	  if (bySortOrder !== 0) {
6	    return bySortOrder;
7	  }
8	
9	  const byCreatedAt =
10	    new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
11	  if (byCreatedAt !== 0) {
12	    return byCreatedAt;
13	  }
14	
15	  return a.id.localeCompare(b.id);
16	}
17	
18	export function sortProjectsByOrder(projects: Project[]): Project[] {
19	  return [...projects].sort(compareProjectsByOrder);
20	}
21	
22	export function getFirstProjectByOrder(projects: Project[]): Project | null {
23	  if (projects.length === 0) {
24	    return null;
25	  }
26	
27	  return sortProjectsByOrder(projects)[0];
28	}
