1	function isSlashCommandPrompt(prompt: string): boolean {
2	  const trimmed = prompt.trimStart();
3	  if (!trimmed.startsWith('/')) return false;
4	
5	  const match = /^\/([^\s/]+)(?:\s|$)/.exec(trimmed);
6	  if (!match) return false;
7	
8	  return true;
9	}
10	
11	export function buildAgentPrompt(
12	  rawUserMessage: string,
13	  contextParts: (string | null | undefined)[]
14	) {
15	  const trimmed = rawUserMessage.trim();
16	  const isSlashCommand = !!trimmed && isSlashCommandPrompt(trimmed);
17	
18	  const parts = isSlashCommand
19	    ? [trimmed]
20	    : [...contextParts, rawUserMessage].filter(Boolean);
21	
22	  return {
23	    prompt: parts.join('\n\n'),
24	    isSlashCommand,
25	  };
26	}
