1	import type {
2	  BaseCodingAgent,
3	  ExecutorProfile,
4	  ModelInfo,
5	  ModelProvider,
6	} from 'shared/types';
7	
8	type ProfilesMap = Record<string, ExecutorProfile> | null;
9	
10	const MAX_RECENT_MODELS = 20;
11	
12	export function getModelKey(model: ModelInfo): string {
13	  return model.provider_id ? `${model.provider_id}/${model.id}` : model.id;
14	}
15	
16	export function getRecentModelEntries(
17	  profiles: ProfilesMap,
18	  executor: BaseCodingAgent | null
19	): string[] {
20	  if (!profiles || !executor) return [];
21	  const entries = profiles[executor]?.recently_used_models?.models ?? [];
22	  return entries.map((e) => e.trim()).filter(Boolean);
23	}
24	
25	export function getRecentReasoningByModel(
26	  profiles: ProfilesMap,
27	  executor: BaseCodingAgent | null
28	): Record<string, string> {
29	  if (!profiles || !executor) return {};
30	  const raw = profiles[executor]?.recently_used_models?.reasoning_by_model;
31	  if (!raw) return {};
32	  const out: Record<string, string> = {};
33	  for (const [k, v] of Object.entries(raw)) {
34	    if (v) out[k] = v;
35	  }
36	  return out;
37	}
38	
39	/**
40	 * Touch a model in the LRU list: move it to the end (most recent).
41	 * If the model doesn't exist, append it. Caps list at MAX_RECENT_MODELS.
42	 */
43	export function touchRecentModel(
44	  entries: string[],
45	  model: ModelInfo
46	): string[] {
47	  const key = getModelKey(model);
48	  const keyLower = key.toLowerCase();
49	  const filtered = entries.filter((e) => e.toLowerCase() !== keyLower);
50	  const updated = [...filtered, key];
51	  if (updated.length > MAX_RECENT_MODELS) {
52	    return updated.slice(updated.length - MAX_RECENT_MODELS);
53	  }
54	  return updated;
55	}
56	
57	export function updateRecentModelEntries(
58	  profiles: Record<string, ExecutorProfile>,
59	  executor: BaseCodingAgent,
60	  entries: string[],
61	  reasoningByModel?: Record<string, string>
62	): Record<string, ExecutorProfile> {
63	  const normalized = entries.map((e) => e.trim()).filter(Boolean);
64	  const existing = profiles[executor]?.recently_used_models;
65	  const mergedReasoning = reasoningByModel ?? existing?.reasoning_by_model;
66	  const recentModels =
67	    normalized.length > 0 ||
68	    (mergedReasoning && Object.keys(mergedReasoning).length > 0)
69	      ? {
70	          ...(normalized.length > 0 ? { models: normalized } : {}),
71	          ...(mergedReasoning && Object.keys(mergedReasoning).length > 0
72	            ? { reasoning_by_model: mergedReasoning }
73	            : {}),
74	        }
75	      : null;
76	  const existingConfig = profiles[executor] ?? {};
77	
78	  return {
79	    ...profiles,
80	    [executor]: {
81	      ...existingConfig,
82	      recently_used_models: recentModels,
83	    } as ExecutorProfile,
84	  };
85	}
86	
87	export function setRecentReasoning(
88	  profiles: Record<string, ExecutorProfile>,
89	  executor: BaseCodingAgent,
90	  model: ModelInfo,
91	  reasoningId: string | null
92	): Record<string, ExecutorProfile> {
93	  const existing = getRecentReasoningByModel(profiles, executor);
94	  const key = getModelKey(model);
95	  const updated = { ...existing };
96	  if (reasoningId) {
97	    updated[key] = reasoningId;
98	  } else {
99	    delete updated[key];
100	  }
101	  const entries = getRecentModelEntries(profiles, executor);
102	  return updateRecentModelEntries(profiles, executor, entries, updated);
103	}
104	
105	/**
106	 * Get the index of a model in the LRU list (-1 if not found).
107	 * Higher index = more recently used.
108	 */
109	export function getRecentIndex(
110	  recentEntries: string[],
111	  model: ModelInfo
112	): number {
113	  const key = getModelKey(model).toLowerCase();
114	  return recentEntries.findIndex((e) => e.toLowerCase() === key);
115	}
116	
117	/**
118	 * Sort models by recency. Defaults to bottom-weighted ordering:
119	 * recent items last and non-recent reversed for bottom-up reading.
120	 */
121	export type RecentAlignment = 'top' | 'bottom';
122	
123	export function sortByRecency(
124	  models: ModelInfo[],
125	  recentEntries: string[],
126	  align: RecentAlignment = 'bottom'
127	): ModelInfo[] {
128	  if (recentEntries.length === 0) {
129	    return align === 'bottom' ? [...models].reverse() : [...models];
130	  }
131	  const recentMap = new Map(recentEntries.map((e, i) => [e.toLowerCase(), i]));
132	
133	  // Separate into non-recent and recent groups
134	  const nonRecent: ModelInfo[] = [];
135	  const recent: { model: ModelInfo; idx: number }[] = [];
136	
137	  for (const model of models) {
138	    const key = getModelKey(model).toLowerCase();
139	    const idx = recentMap.get(key) ?? -1;
140	    if (idx === -1) {
141	      nonRecent.push(model);
142	    } else {
143	      recent.push({ model, idx });
144	    }
145	  }
146	
147	  // Non-recent: reversed original order (bottom-up reading)
148	  if (align === 'bottom') {
149	    nonRecent.reverse();
150	  }
151	
152	  // Recent: sorted by recency (higher index = more recent)
153	  recent.sort((a, b) => (align === 'bottom' ? a.idx - b.idx : b.idx - a.idx));
154	
155	  if (align === 'top') {
156	    return [...recent.map((r) => r.model), ...nonRecent];
157	  }
158	  return [...nonRecent, ...recent.map((r) => r.model)];
159	}
160	
161	export function sortProvidersByRecency(
162	  providers: ModelProvider[],
163	  models: ModelInfo[],
164	  recentEntries: string[]
165	): ModelProvider[] {
166	  const baseProviders = [...providers].reverse();
167	  if (recentEntries.length === 0) return baseProviders;
168	
169	  const recencyByProvider = new Map<string, number>();
170	  for (const model of models) {
171	    if (!model.provider_id) continue;
172	    const idx = getRecentIndex(recentEntries, model);
173	    if (idx === -1) continue;
174	    const current = recencyByProvider.get(model.provider_id) ?? -1;
175	    if (idx > current) {
176	      recencyByProvider.set(model.provider_id, idx);
177	    }
178	  }
179	
180	  const order = new Map(
181	    baseProviders.map((provider, index) => [provider.id, index])
182	  );
183	
184	  return [...baseProviders].sort((a, b) => {
185	    const aRecent = recencyByProvider.get(a.id) ?? -1;
186	    const bRecent = recencyByProvider.get(b.id) ?? -1;
187	    if (aRecent === -1 && bRecent === -1) {
188	      return (order.get(a.id) ?? 0) - (order.get(b.id) ?? 0);
189	    }
190	    if (aRecent === -1) return -1;
191	    if (bRecent === -1) return 1;
192	    if (aRecent === bRecent) {
193	      return (order.get(a.id) ?? 0) - (order.get(b.id) ?? 0);
194	    }
195	    return aRecent - bRecent;
196	  });
197	}
