123	async function makeAuthenticatedRequest(
124	  baseUrl: string,
125	  path: string,
126	  options: RequestInit = {},
127	  retryOn401 = true
128	): Promise<Response> {
129	  const authRuntime = getAuthRuntime();
130	  const token = await authRuntime.getToken();
131	  if (!token) {
132	    throw new Error('Not authenticated');
133	  }
134	
135	  const headers = new Headers(options.headers ?? {});
136	  if (!headers.has('Content-Type')) {
137	    headers.set('Content-Type', 'application/json');
138	  }
139	  headers.set('Authorization', `Bearer ${token}`);
140	  headers.set('X-Client-Version', __APP_VERSION__);
141	  headers.set('X-Client-Type', 'frontend');
142	
143	  const response = await fetch(`${baseUrl}${path}`, {
144	    ...options,
145	    headers,
146	    credentials: 'include',
147	  });
148	
149	  if (response.status === 401 && retryOn401) {
150	    const newToken = await authRuntime.triggerRefresh();
151	    if (newToken) {
152	      headers.set('Authorization', `Bearer ${newToken}`);
153	      return fetch(`${baseUrl}${path}`, {
154	        ...options,
155	        headers,
156	        credentials: 'include',
157	      });
158	    }
159	
160	    throw new Error('Session expired. Please log in again.');
161	  }
162	
163	  return response;
164	}
