166	async function parseErrorResponse(
167	  response: Response,
168	  fallbackMessage: string
169	): Promise<Error> {
170	  try {
171	    const body = await response.json();
172	    const message = body.error || body.message || fallbackMessage;
173	    return new Error(`${message} (${response.status} ${response.statusText})`);
174	  } catch {
175	    return new Error(
176	      `${fallbackMessage} (${response.status} ${response.statusText})`
177	    );
178	  }
179	}
