190	function parseRelaySessionBaseUrl(finalUrl: string, hostId: string): string {
191	  const parsed = new URL(finalUrl);
192	  const hostPattern = escapeRegExp(hostId);
193	  const match = parsed.pathname.match(
194	    new RegExp(`^/relay/h/${hostPattern}/s/[^/]+`)
195	  );
196	  if (!match) {
197	    throw new Error('Failed to establish relay browser session.');
198	  }
