207	interface LocalApiSuccess<T> {
208	  success: true;
209	  data: T;
210	}
211	
212	interface LocalApiFailure {
213	  success: false;
214	  message?: string;
215	}
216	
217	type LocalApiEnvelope<T> = LocalApiSuccess<T> | LocalApiFailure;
218	
219	async function parseLocalApiResponse<T>(
220	  response: Response,
221	  fallbackMessage: string
222	): Promise<T> {
223	  if (!response.ok) {
224	    throw new Error(await extractErrorMessage(response, fallbackMessage));
225	  }
226	
227	  const body = (await response.json()) as LocalApiEnvelope<T>;
228	  if (!body.success) {
229	    throw new Error(body.message || fallbackMessage);
230	  }
231	
232	  return body.data;
233	}
234	
235	async function extractErrorMessage(
236	  response: Response,
237	  fallbackMessage: string
238	): Promise<string> {
239	  try {
240	    const body = await response.json();
241	    if (body && typeof body.message === 'string') {
242	      return body.message;
243	    }
244	    if (body && typeof body.error === 'string') {
245	      return body.error;
246	    }
247	  } catch {
248	    // Ignore parse failures and use fallback.
249	  }
250	
251	  return `${fallbackMessage} (${response.status})`;
252	}
