25	function detectBrowser(userAgent: string): string {
26	  if (/Edg\//.test(userAgent)) return 'Edge';
27	  if (/OPR\//.test(userAgent)) return 'Opera';
28	  if (/Firefox\//.test(userAgent)) return 'Firefox';
29	  if (/Chrome\//.test(userAgent) || /CriOS\//.test(userAgent)) return 'Chrome';
30	  if (/Safari\//.test(userAgent)) return 'Safari';
31	  return 'Unknown Browser';
