34	function detectOs(userAgent: string): string {
35	  if (/Windows NT/.test(userAgent)) return 'Windows';
36	  if (/iPhone|iPad|iPod/.test(userAgent)) return 'iOS';
37	  if (/Macintosh|Mac OS X/.test(userAgent)) return 'macOS';
38	  if (/Android/.test(userAgent)) return 'Android';
39	  if (/Linux/.test(userAgent)) return 'Linux';
40	  return 'Unknown OS';
41	}
