43	function detectDevice(userAgent: string): string {
44	  if (/iPad|Tablet|PlayBook|Silk/.test(userAgent)) return 'tablet';
45	  if (/Mobi|Android|iPhone|iPod/.test(userAgent)) return 'mobile';
46	  return 'desktop';
47	}
