1	const DB_NAME = 'vk-relay-pairing';
2	const DB_VERSION = 1;
3	const PAIRED_HOSTS_STORE = 'paired_hosts';
4	
5	type RelayPairingChangeType = 'saved' | 'removed';
6	
7	export interface RelayPairingChange {
8	  hostId: string;
9	  type: RelayPairingChangeType;
10	}
11	
12	type RelayPairingChangeListener = (change: RelayPairingChange) => void;
13	
14	const relayPairingChangeListeners = new Set<RelayPairingChangeListener>();
15	
16	export interface PairedRelayHost {
17	  host_id: string;
18	  host_name: string;
19	  client_id?: string;
20	  client_name?: string;
21	  signing_session_id?: string;
