23	  private_key_jwk: JsonWebKey;
24	  server_public_key_b64: string;
25	  paired_at: string;
26	}
27	
28	export function subscribeRelayPairingChanges(
29	  listener: RelayPairingChangeListener
30	): () => void {
31	  relayPairingChangeListeners.add(listener);
32	  return () => {
33	    relayPairingChangeListeners.delete(listener);
34	  };
35	}
36	
37	function emitRelayPairingChange(change: RelayPairingChange): void {
38	  for (const listener of relayPairingChangeListeners) {
39	    try {
40	      listener(change);
41	    } catch (error) {
42	      console.error('relay pairing change listener failed', error);
43	    }
44	  }
45	}
