47	function openDb(): Promise<IDBDatabase> {
48	  return new Promise((resolve, reject) => {
49	    const request = indexedDB.open(DB_NAME, DB_VERSION);
50	
51	    request.onupgradeneeded = () => {
52	      const db = request.result;
53	      if (!db.objectStoreNames.contains(PAIRED_HOSTS_STORE)) {
54	        db.createObjectStore(PAIRED_HOSTS_STORE, { keyPath: 'host_id' });
55	      }
56	    };
57	
58	    request.onsuccess = () => resolve(request.result);
59	    request.onerror = () => reject(request.error);
60	  });
61	}
62	
63	export async function listPairedRelayHosts(): Promise<PairedRelayHost[]> {
64	  const db = await openDb();
65	  return new Promise<PairedRelayHost[]>((resolve, reject) => {
66	    const tx = db.transaction(PAIRED_HOSTS_STORE, 'readonly');
67	    const store = tx.objectStore(PAIRED_HOSTS_STORE);
68	    const request = store.getAll();
69	
70	    request.onsuccess = () => {
71	      const pairedHosts = (request.result as PairedRelayHost[]) ?? [];
72	      pairedHosts.sort((a, b) => b.paired_at.localeCompare(a.paired_at));
73	      resolve(pairedHosts);
74	    };
75	    request.onerror = () => reject(request.error);
76	    tx.onerror = () => reject(tx.error);
77	    tx.onabort = () => reject(tx.error);
78	    tx.oncomplete = () => {
79	      db.close();
80	    };
81	  });
82	}
83	
84	export async function savePairedRelayHost(
85	  host: PairedRelayHost
86	): Promise<void> {
87	  const db = await openDb();
88	  await new Promise<void>((resolve, reject) => {
89	    const tx = db.transaction(PAIRED_HOSTS_STORE, 'readwrite');
90	    const store = tx.objectStore(PAIRED_HOSTS_STORE);
91	    const request = store.put(host);
92	
93	    request.onerror = () => reject(request.error);
94	    tx.onerror = () => reject(tx.error);
95	    tx.onabort = () => reject(tx.error);
96	    tx.oncomplete = () => {
97	      db.close();
98	      emitRelayPairingChange({ hostId: host.host_id, type: 'saved' });
99	      resolve();
100	    };
101	  });
102	}
103	
104	export async function removePairedRelayHost(hostId: string): Promise<void> {
105	  const db = await openDb();
106	  await new Promise<void>((resolve, reject) => {
107	    const tx = db.transaction(PAIRED_HOSTS_STORE, 'readwrite');
108	    const store = tx.objectStore(PAIRED_HOSTS_STORE);
109	    const request = store.delete(hostId);
110	
111	    request.onerror = () => reject(request.error);
112	    tx.onerror = () => reject(tx.error);
113	    tx.onabort = () => reject(tx.error);
114	    tx.oncomplete = () => {
115	      db.close();
116	      emitRelayPairingChange({ hostId, type: 'removed' });
117	      resolve();
118	    };
119	  });
120	}
