1	import { ed25519 } from '@noble/curves/ed25519';
2	
3	const ENCODER = new TextEncoder();
4	
5	const SPAKE2_CLIENT_ID = ENCODER.encode('vibe-kanban-browser');
6	const SPAKE2_SERVER_ID = ENCODER.encode('vibe-kanban-server');
7	
8	const KEY_CONFIRMATION_INFO = ENCODER.encode('key-confirmation');
9	const CLIENT_PROOF_CONTEXT = ENCODER.encode('vk-spake2-client-proof-v2');
10	const SERVER_PROOF_CONTEXT = ENCODER.encode('vk-spake2-server-proof-v2');
11	
12	const SPAKE2_PASSWORD_INFO = ENCODER.encode('SPAKE2 pw');
13	const ENROLLMENT_CODE_LENGTH = 6;
14	
15	// Ed25519 subgroup order (same value used in curve25519-dalek).
16	const CURVE_ORDER =
17	  7237005577332262213973186563042994240857116359379907606001950938285454250989n;
18	
19	const SPAKE2_M = ed25519.ExtendedPoint.fromHex(
20	  '15cfd18e385952982b6a8f8c7854963b58e34388c8e6dae891db756481a02312'
21	);
22	const SPAKE2_N = ed25519.ExtendedPoint.fromHex(
23	  'f04f2e7eb734b2a8f8b472eaf9c3c632576ac64aea650b496a8a20ff00e583c3'
24	);
25	
26	export interface Spake2EnrollmentClientState {
27	  passwordBytes: Uint8Array;
28	  passwordScalar: bigint;
29	  xScalar: bigint;
30	  clientMessageBytes: Uint8Array;
31	}
32	
33	export function normalizeEnrollmentCode(rawCode: string): string {
34	  return rawCode
35	    .trim()
36	    .toUpperCase()
37	    .replace(/[^A-Z0-9]/g, '');
38	}
39	
40	export async function startSpake2Enrollment(
41	  rawEnrollmentCode: string
42	): Promise<{ state: Spake2EnrollmentClientState; clientMessageB64: string }> {
43	  const enrollmentCode = normalizeEnrollmentCode(rawEnrollmentCode);
44	  if (enrollmentCode.length !== ENROLLMENT_CODE_LENGTH) {
45	    throw new Error('Enrollment code must be 6 characters.');
46	  }
47	
48	  const passwordBytes = ENCODER.encode(enrollmentCode);
49	  const passwordScalar = await hashToSpake2Scalar(passwordBytes);
50	  const xScalar = randomScalar();
51	
52	  const clientPoint = ed25519.ExtendedPoint.BASE.multiply(xScalar).add(
53	    SPAKE2_M.multiply(passwordScalar)
54	  );
55	  const clientPointBytes = clientPoint.toRawBytes();
56	
57	  const clientMessage = new Uint8Array(1 + clientPointBytes.length);
58	  clientMessage[0] = 0x41; // 'A'
59	  clientMessage.set(clientPointBytes, 1);
60	
61	  return {
62	    state: {
63	      passwordBytes,
64	      passwordScalar,
65	      xScalar,
66	      clientMessageBytes: clientPointBytes,
67	    },
68	    clientMessageB64: bytesToBase64(clientMessage),
69	  };
70	}
71	
72	export async function finishSpake2Enrollment(
73	  state: Spake2EnrollmentClientState,
74	  serverMessageB64: string
75	): Promise<Uint8Array> {
76	  const serverMessage = base64ToBytes(serverMessageB64);
77	  if (serverMessage.length !== 33) {
78	    throw new Error('Server message has invalid length.');
79	  }
80	  if (serverMessage[0] !== 0x42) {
81	    throw new Error('Server message has invalid side identifier.');
82	  }
83	
84	  const serverPointBytes = serverMessage.slice(1);
85	  const serverPoint = ed25519.ExtendedPoint.fromHex(serverPointBytes);
86	  const negativePasswordScalar =
87	    (CURVE_ORDER - state.passwordScalar) % CURVE_ORDER;
88	
89	  const keyPoint = serverPoint
90	    .add(SPAKE2_N.multiply(negativePasswordScalar))
91	    .multiply(state.xScalar);
92	  const keyPointBytes = keyPoint.toRawBytes();
93	
94	  return hashAb(
95	    state.passwordBytes,
96	    SPAKE2_CLIENT_ID,
97	    SPAKE2_SERVER_ID,
98	    state.clientMessageBytes,
99	    serverPointBytes,
100	    keyPointBytes
101	  );
102	}
