104	export async function generateRelaySigningKeyPair(): Promise<{
105	  privateKeyJwk: JsonWebKey;
106	  publicKeyBytes: Uint8Array;
107	  publicKeyB64: string;
108	}> {
109	  const keyPair = (await crypto.subtle.generateKey({ name: 'Ed25519' }, true, [
110	    'sign',
111	    'verify',
112	  ])) as CryptoKeyPair;
113	
114	  const [privateKeyJwk, publicKeyRaw] = await Promise.all([
115	    crypto.subtle.exportKey('jwk', keyPair.privateKey),
116	    crypto.subtle.exportKey('raw', keyPair.publicKey),
117	  ]);
118	
119	  const publicKeyBytes = new Uint8Array(publicKeyRaw);
120	  return {
121	    privateKeyJwk,
122	    publicKeyBytes,
123	    publicKeyB64: bytesToBase64(publicKeyBytes),
124	  };
125	}
