127	export async function buildClientProofB64(
128	  sharedKey: Uint8Array,
129	  enrollmentId: string,
130	  browserPublicKeyBytes: Uint8Array
131	): Promise<string> {
132	  const confirmationKey = await deriveConfirmationKey(sharedKey);
133	  const enrollmentIdBytes = uuidToBytes(enrollmentId);
134	  const payload = concatBytes(
135	    CLIENT_PROOF_CONTEXT,
136	    enrollmentIdBytes,
137	    browserPublicKeyBytes
138	  );
139	  const proof = await hmacSha256(confirmationKey, payload);
140	  return bytesToBase64(proof);
141	}
142	
143	export async function verifyServerProof(
144	  sharedKey: Uint8Array,
145	  enrollmentId: string,
146	  browserPublicKeyBytes: Uint8Array,
147	  serverPublicKeyB64: string,
148	  serverProofB64: string
149	): Promise<boolean> {
150	  const confirmationKey = await deriveConfirmationKey(sharedKey);
151	  const enrollmentIdBytes = uuidToBytes(enrollmentId);
152	  const serverPublicKeyBytes = base64ToBytes(serverPublicKeyB64);
153	
154	  const payload = concatBytes(
155	    SERVER_PROOF_CONTEXT,
156	    enrollmentIdBytes,
157	    browserPublicKeyBytes,
158	    serverPublicKeyBytes
159	  );
160	  const expectedProof = await hmacSha256(confirmationKey, payload);
161	  const actualProof = base64ToBytes(serverProofB64);
162	
163	  return constantTimeEqual(expectedProof, actualProof);
164	}
165	
166	async function hashAb(
167	  passwordBytes: Uint8Array,
168	  idA: Uint8Array,
169	  idB: Uint8Array,
170	  firstMessage: Uint8Array,
171	  secondMessage: Uint8Array,
172	  keyBytes: Uint8Array
173	): Promise<Uint8Array> {
174	  const transcript = new Uint8Array(6 * 32);
175	
176	  transcript.set(await sha256(passwordBytes), 0);
177	  transcript.set(await sha256(idA), 32);
178	  transcript.set(await sha256(idB), 64);
179	  transcript.set(firstMessage, 96);
180	  transcript.set(secondMessage, 128);
181	  transcript.set(keyBytes, 160);
182	
183	  return sha256(transcript);
184	}
185	
186	async function hashToSpake2Scalar(passwordBytes: Uint8Array): Promise<bigint> {
187	  const okm = await hkdfSha256(
188	    passwordBytes,
189	    new Uint8Array(0),
190	    SPAKE2_PASSWORD_INFO,
191	    48
192	  );
193	
194	  const reducible = new Uint8Array(64);
195	  for (let i = 0; i < okm.length; i += 1) {
196	    reducible[okm.length - 1 - i] = okm[i];
197	  }
198	
199	  return bytesToBigIntLE(reducible) % CURVE_ORDER;
200	}
201	
202	function randomScalar(): bigint {
203	  const randomBytes = new Uint8Array(64);
204	  crypto.getRandomValues(randomBytes);
205	  return bytesToBigIntLE(randomBytes) % CURVE_ORDER;
206	}
207	
208	async function deriveConfirmationKey(
209	  sharedKey: Uint8Array
210	): Promise<Uint8Array> {
211	  return hkdfSha256(sharedKey, new Uint8Array(0), KEY_CONFIRMATION_INFO, 32);
212	}
213	
214	async function hkdfSha256(
215	  ikm: Uint8Array,
216	  salt: Uint8Array,
217	  info: Uint8Array,
218	  length: number
219	): Promise<Uint8Array> {
220	  const key = await crypto.subtle.importKey(
221	    'raw',
222	    toArrayBuffer(ikm),
223	    'HKDF',
224	    false,
225	    ['deriveBits']
226	  );
227	  const derivedBits = await crypto.subtle.deriveBits(
228	    {
229	      name: 'HKDF',
230	      hash: 'SHA-256',
231	      salt: toArrayBuffer(salt),
232	      info: toArrayBuffer(info),
233	    },
234	    key,
235	    length * 8
236	  );
237	  return new Uint8Array(derivedBits);
238	}
239	
240	async function hmacSha256(
241	  keyBytes: Uint8Array,
242	  data: Uint8Array
243	): Promise<Uint8Array> {
244	  const key = await crypto.subtle.importKey(
245	    'raw',
246	    toArrayBuffer(keyBytes),
247	    { name: 'HMAC', hash: 'SHA-256' },
248	    false,
249	    ['sign']
250	  );
251	  const signature = await crypto.subtle.sign('HMAC', key, toArrayBuffer(data));
252	  return new Uint8Array(signature);
253	}
254	
255	async function sha256(data: Uint8Array): Promise<Uint8Array> {
256	  const digest = await crypto.subtle.digest('SHA-256', toArrayBuffer(data));
257	  return new Uint8Array(digest);
258	}
259	
260	function toArrayBuffer(data: Uint8Array): ArrayBuffer {
261	  return new Uint8Array(data).buffer;
262	}
263	
264	function uuidToBytes(rawUuid: string): Uint8Array {
265	  const hex = rawUuid.replace(/-/g, '');
266	  if (hex.length !== 32) {
267	    throw new Error('Invalid enrollment ID.');
268	  }
269	
270	  const bytes = new Uint8Array(16);
271	  for (let i = 0; i < 16; i += 1) {
272	    const value = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
273	    if (Number.isNaN(value)) {
274	      throw new Error('Invalid enrollment ID.');
275	    }
276	    bytes[i] = value;
277	  }
278	
279	  return bytes;
280	}
281	
282	function bytesToBigIntLE(bytes: Uint8Array): bigint {
283	  let value = 0n;
284	  for (let i = bytes.length - 1; i >= 0; i -= 1) {
285	    value = (value << 8n) + BigInt(bytes[i]);
286	  }
287	  return value;
288	}
289	
290	function concatBytes(...chunks: Uint8Array[]): Uint8Array {
291	  const totalLength = chunks.reduce((sum, chunk) => sum + chunk.length, 0);
292	  const output = new Uint8Array(totalLength);
293	  let offset = 0;
294	  for (const chunk of chunks) {
295	    output.set(chunk, offset);
296	    offset += chunk.length;
297	  }
298	  return output;
299	}
300	
301	function constantTimeEqual(a: Uint8Array, b: Uint8Array): boolean {
302	  if (a.length !== b.length) {
303	    return false;
304	  }
305	  let mismatch = 0;
306	  for (let i = 0; i < a.length; i += 1) {
307	    mismatch |= a[i] ^ b[i];
308	  }
309	  return mismatch === 0;
310	}
311	
312	function bytesToBase64(bytes: Uint8Array): string {
313	  const binary = String.fromCharCode(...bytes);
314	  return btoa(binary);
315	}
316	
317	function base64ToBytes(value: string): Uint8Array {
318	  const binary = atob(value);
319	  const bytes = new Uint8Array(binary.length);
320	  for (let i = 0; i < binary.length; i += 1) {
321	    bytes[i] = binary.charCodeAt(i);
322	  }
323	  return bytes;
324	}
