1	import type { RelaySigningSessionRefreshPayload } from '@/shared/lib/relayBackendApi';
2	
3	const TEXT_ENCODER = new TextEncoder();
4	
5	export function buildRelaySigningSessionRefreshMessage(
6	  timestamp: number,
7	  nonce: string,
8	  clientId: string
9	): string {
10	  return `v1|refresh|${timestamp}|${nonce}|${clientId}`;
11	}
12	
13	export async function buildRelaySigningSessionRefreshPayload(
14	  clientId: string,
15	  privateKeyJwk: JsonWebKey
16	): Promise<RelaySigningSessionRefreshPayload> {
17	  const timestamp = Math.floor(Date.now() / 1000);
18	  const nonce = crypto.randomUUID().replace(/-/g, '');
19	  const message = buildRelaySigningSessionRefreshMessage(
20	    timestamp,
21	    nonce,
22	    clientId
23	  );
24	  const key = await crypto.subtle.importKey(
25	    'jwk',
26	    privateKeyJwk,
27	    { name: 'Ed25519' },
28	    false,
29	    ['sign']
30	  );
31	  const signature = await crypto.subtle.sign(
32	    'Ed25519',
33	    key,
34	    toArrayBuffer(TEXT_ENCODER.encode(message))
35	  );
36	
37	  return {
38	    client_id: clientId,
39	    timestamp,
40	    nonce,
41	    signature_b64: bytesToBase64(new Uint8Array(signature)),
42	  };
43	}
44	
45	function bytesToBase64(bytes: Uint8Array): string {
46	  let binary = '';
47	  for (const value of bytes) {
48	    binary += String.fromCharCode(value);
49	  }
50	  return btoa(binary);
51	}
52	
53	function toArrayBuffer(bytes: Uint8Array): ArrayBuffer {
54	  return bytes.buffer.slice(
55	    bytes.byteOffset,
56	    bytes.byteOffset + bytes.byteLength
57	  ) as ArrayBuffer;
58	}
