48	export const makeRequest = async (
49	  path: string,
50	  options: RequestInit = {},
51	  retryOn401 = true
52	): Promise<Response> => {
53	  return makeAuthenticatedRequest(getRemoteApiUrl(), path, options, retryOn401);
