56	async function makeAuthenticatedRequest(
57	  baseUrl: string,
58	  path: string,
59	  options: RequestInit = {},
60	  retryOn401 = true
61	): Promise<Response> {
62	  const authRuntime = getAuthRuntime();
63	  const token = await authRuntime.getToken();
64	  if (!token) {
65	    throw new Error('Not authenticated');
66	  }
67	
68	  const headers = new Headers(options.headers ?? {});
69	  if (!headers.has('Content-Type')) {
70	    headers.set('Content-Type', 'application/json');
71	  }
72	  headers.set('Authorization', `Bearer ${token}`);
73	  headers.set('X-Client-Version', __APP_VERSION__);
74	  headers.set('X-Client-Type', 'frontend');
75	
76	  const response = await fetch(`${baseUrl}${path}`, {
77	    ...options,
78	    headers,
79	    credentials: 'include',
80	  });
81	
82	  // Handle 401 - token may have expired
83	  if (response.status === 401 && retryOn401) {
84	    const newToken = await authRuntime.triggerRefresh();
85	    if (newToken) {
86	      // Retry the request with the new token
87	      headers.set('Authorization', `Bearer ${newToken}`);
88	      return fetch(`${baseUrl}${path}`, {
89	        ...options,
90	        headers,
91	        credentials: 'include',
92	      });
93	    }
94	    // Refresh failed, throw an auth error
95	    throw new Error('Session expired. Please log in again.');
96	  }
97	
98	  return response;
99	}
