190	// SAS URL cache with TTL — SAS URLs expire after 5 minutes, cache for 4
191	// ---------------------------------------------------------------------------
192	
193	const SAS_URL_TTL_MS = 4 * 60 * 1000;
194	
195	interface CachedSasUrl {
196	  url: string;
197	  expiresAt: number;
198	}
199	
200	const sasUrlCache = new Map<string, CachedSasUrl>();
