202	// ---------------------------------------------------------------------------
203	// Utility: SHA-256 file hash
204	// ---------------------------------------------------------------------------
205	
206	export async function computeFileHash(file: File): Promise<string> {
207	  const buffer = await file.arrayBuffer();
208	  const hash = await crypto.subtle.digest('SHA-256', buffer);
209	  return Array.from(new Uint8Array(hash))
210	    .map((b) => b.toString(16).padStart(2, '0'))
211	    .join('');
212	}
