214	// ---------------------------------------------------------------------------
215	// Utility: Upload to Azure Blob Storage with progress
216	// ---------------------------------------------------------------------------
217	
218	export function uploadToAzure(
219	  uploadUrl: string,
220	  file: File,
221	  onProgress?: (pct: number) => void
222	): Promise<void> {
223	  return new Promise((resolve, reject) => {
224	    const xhr = new XMLHttpRequest();
225	    xhr.open('PUT', uploadUrl, true);
226	    xhr.setRequestHeader('x-ms-blob-type', 'BlockBlob');
227	    xhr.setRequestHeader('Content-Type', file.type);
228	
229	    if (onProgress) {
230	      xhr.upload.addEventListener('progress', (e) => {
231	        if (e.lengthComputable) {
232	          onProgress(Math.round((e.loaded / e.total) * 100));
233	        }
234	      });
235	    }
236	
237	    xhr.onload = () => {
238	      if (xhr.status === 201) {
239	        resolve();
240	      } else {
241	        reject(
242	          new Error(
243	            `Azure upload failed with status ${xhr.status}: ${xhr.statusText}`
244	          )
245	        );
246	      }
247	    };
248	
249	    xhr.onerror = () => {
250	      reject(new Error('Azure upload failed: network error'));
251	    };
252	
253	    xhr.send(file);
254	  });
255	}
