258	// Utility: safe error response parsing (handles non-JSON error bodies)
259	// ---------------------------------------------------------------------------
260	
261	async function parseErrorResponse(
262	  response: Response,
263	  fallbackMessage: string
264	): Promise<Error> {
265	  try {
266	    const body = await response.json();
267	    const message = body.error || body.message || fallbackMessage;
268	    return new Error(`${message} (${response.status} ${response.statusText})`);
269	  } catch {
270	    return new Error(
271	      `${fallbackMessage} (${response.status} ${response.statusText})`
272	    );
273	  }
274	}
