17	export function resolveRelationshipsForIssue(
18	  issueId: string,
19	  relationships: IssueRelationship[],
20	  issuesById: Map<string, Issue>
21	): ResolvedRelationship[] {
22	  return relationships
23	    .map((r) => {
24	      const isSource = r.issue_id === issueId;
25	      const otherIssueId = isSource ? r.related_issue_id : r.issue_id;
26	      const otherIssue = issuesById.get(otherIssueId);
27	      if (!otherIssue) return null;
28	
29	      let displayType: RelationshipDisplayType;
30	      if (r.relationship_type === 'blocking') {
31	        displayType = isSource ? 'blocks' : 'blocked_by';
32	      } else if (r.relationship_type === 'related') {
33	        displayType = 'related';
34	      } else {
35	        displayType = isSource ? 'duplicate_of' : 'duplicated_by';
36	      }
37	
38	      return {
39	        relationshipId: r.id,
40	        displayType,
41	        relatedIssueId: otherIssueId,
42	        relatedIssueDisplayId: otherIssue.simple_id,
43	      };
44	    })
45	    .filter((r): r is ResolvedRelationship => r !== null);
46	}
