1	// streamJsonPatchEntries.ts - WebSocket JSON patch streaming utility
2	import { produce } from 'immer';
3	import type { Operation } from 'rfc6902';
4	import { applyUpsertPatch } from '@/shared/lib/jsonPatch';
5	import { openLocalApiWebSocket } from '@/shared/lib/localApiTransport';
6	
7	type PatchContainer<E = unknown> = { entries: E[] };
8	
9	export interface StreamOptions<E = unknown> {
10	  initial?: PatchContainer<E>;
11	  /** called after each successful patch application */
12	  onEntries?: (entries: E[]) => void;
13	  onConnect?: () => void;
14	  onError?: (err: unknown) => void;
15	  /** called once when a "finished" event is received */
16	  onFinished?: (entries: E[]) => void;
17	}
18	
19	interface StreamController<E = unknown> {
20	  /** Current entries array (immutable snapshot) */
21	  getEntries(): E[];
22	  /** Full { entries } snapshot */
23	  getSnapshot(): PatchContainer<E>;
24	  /** Best-effort connection state */
25	  isConnected(): boolean;
26	  /** Subscribe to updates; returns an unsubscribe function */
27	  onChange(cb: (entries: E[]) => void): () => void;
28	  /** Close the stream */
29	  close(): void;
30	}
31	
32	/**
33	 * Connect to a WebSocket endpoint that emits JSON messages containing:
34	 *   {"JsonPatch": [{"op": "add", "path": "/entries/0", "value": {...}}, ...]}
35	 *   {"Finished": ""}
36	 *
37	 * Maintains an in-memory { entries: [] } snapshot and returns a controller.
38	 *
39	 * Messages are batched per animation frame and applied using immer for
40	 * structural sharing, avoiding a full deep clone on every message.
41	 */
42	export function streamJsonPatchEntries<E = unknown>(
43	  url: string,
44	  opts: StreamOptions<E> = {}
45	): StreamController<E> {
46	  let connected = false;
47	  let closed = false;
48	  let ws: WebSocket | null = null;
49	  let snapshot: PatchContainer<E> = structuredClone(
50	    opts.initial ?? ({ entries: [] } as PatchContainer<E>)
51	  );
52	
53	  const subscribers = new Set<(entries: E[]) => void>();
54	  if (opts.onEntries) subscribers.add(opts.onEntries);
55	
56	  // --- rAF batching state ---
57	  let pendingOps: Operation[] = [];
58	  let rafId: number | null = null;
59	
60	  const notify = () => {
61	    for (const cb of subscribers) {
62	      try {
63	        cb(snapshot.entries);
64	      } catch {
65	        /* swallow subscriber errors */
66	      }
67	    }
68	  };
69	
70	  const flush = () => {
71	    rafId = null;
72	    if (pendingOps.length === 0) return;
73	
74	    const ops = dedupeOps(pendingOps);
75	    pendingOps = [];
76	
77	    snapshot = produce(snapshot, (draft) => {
78	      applyUpsertPatch(draft, ops);
79	    });
80	    notify();
81	  };
82	
83	  const handleMessage = (event: MessageEvent) => {
84	    try {
85	      const msg = JSON.parse(event.data);
86	
87	      // Handle JsonPatch messages — accumulate ops for next rAF flush
88	      if (msg.JsonPatch) {
89	        const raw = msg.JsonPatch as Operation[];
90	        pendingOps.push(...raw);
91	        if (rafId === null) {
92	          rafId = requestAnimationFrame(flush);
93	        }
94	      }
95	
96	      // Handle Finished messages — flush synchronously before closing
97	      if (msg.finished !== undefined) {
98	        if (rafId !== null) {
99	          cancelAnimationFrame(rafId);
100	        }
101	        flush();
102	        opts.onFinished?.(snapshot.entries);
103	        ws?.close();
104	      }
105	    } catch (err) {
106	      opts.onError?.(err);
107	    }
108	  };
109	
110	  void (async () => {
111	    try {
112	      const opened = await openLocalApiWebSocket(url);
113	
114	      if (closed) {
115	        opened.close();
116	        return;
117	      }
118	
119	      ws = opened;
120	      ws.addEventListener('open', () => {
121	        connected = true;
122	        opts.onConnect?.();
123	      });
124	
125	      ws.addEventListener('message', handleMessage);
126	
127	      ws.addEventListener('error', (err) => {
128	        connected = false;
129	        opts.onError?.(err);
130	      });
131	
132	      ws.addEventListener('close', () => {
133	        connected = false;
134	        if (rafId !== null) {
135	          cancelAnimationFrame(rafId);
136	          rafId = null;
137	        }
138	      });
139	    } catch (error) {
140	      if (!closed) {
141	        opts.onError?.(error);
142	      }
143	    }
144	  })();
145	
146	  return {
147	    getEntries(): E[] {
148	      return snapshot.entries;
149	    },
150	    getSnapshot(): PatchContainer<E> {
151	      return snapshot;
152	    },
153	    isConnected(): boolean {
154	      return connected;
155	    },
156	    onChange(cb: (entries: E[]) => void): () => void {
157	      subscribers.add(cb);
158	      // push current state immediately
159	      cb(snapshot.entries);
160	      return () => subscribers.delete(cb);
161	    },
162	    close(): void {
163	      closed = true;
164	      if (rafId !== null) {
165	        cancelAnimationFrame(rafId);
166	        rafId = null;
167	      }
168	      ws?.close();
169	      subscribers.clear();
170	      connected = false;
171	    },
172	  };
173	}
174	
175	/**
176	 * Dedupe multiple ops that touch the same path within a batch.
177	 * Last write for a path wins, while preserving the overall left-to-right
178	 * order of the *kept* final operations.
179	 *
180	 * Example:
181	 *   add /entries/4, replace /entries/4  -> keep only the final replace
182	 */
183	function dedupeOps(ops: Operation[]): Operation[] {
184	  const lastIndexByPath = new Map<string, number>();
185	  ops.forEach((op, i) => lastIndexByPath.set(op.path, i));
186	
187	  // Keep only the last op for each path, in ascending order of their final index
188	  const keptIndices = [...lastIndexByPath.values()].sort((a, b) => a - b);
189	  return keptIndices.map((i) => ops[i]!);
190	}
