24	/**
25	 * Removes a single trailing newline sequence from a string.
26	 * Handles CRLF/CR/LF endings while leaving other trailing whitespace intact.
27	 */
28	export const stripLineEnding = (value: string): string => {
29	  return value.replace(/(?:\r\n|\r|\n)$/, '');
30	};
31	
32	/**
33	 * Splits a string by newlines and returns an array of lines.
34	 * Handles CRLF, CR, and LF line endings.
35	 */
36	export const splitLines = (value: string): string[] => {
37	  return value.split(/\r\n|\r|\n/);
38	};
