40	/**
41	 * Splits a message into title (max 100 chars) and description.
42	 * - First line becomes the title (truncated at word boundary if > 100 chars)
43	 * - Overflow from first line + remaining lines become description
44	 */
45	export function splitMessageToTitleDescription(message: string): {
46	  title: string;
47	  description: string | null;
48	} {
49	  const trimmed = message.trim();
50	  const lines = trimmed.split('\n');
51	  const firstLine = lines[0];
52	  const restOfLines = lines.slice(1).join('\n').trim();
53	
54	  if (firstLine.length <= 100) {
55	    return {
56	      title: firstLine,
57	      description: restOfLines || null,
58	    };
59	  }
60	
61	  // Find word boundary in first 100 chars
62	  const truncated = firstLine.substring(0, 100);
63	  const lastSpace = truncated.lastIndexOf(' ');
64	
65	  if (lastSpace > 50) {
66	    // Split at word boundary (if at least half the title is preserved)
67	    const title = truncated.substring(0, lastSpace);
68	    const overflow = firstLine.substring(lastSpace + 1);
69	    return {
70	      title,
71	      description: restOfLines ? `${overflow}\n\n${restOfLines}` : overflow,
72	    };
73	  }
74	
75	  // Fall back to character split
76	  const overflow = firstLine.substring(100);
77	  return {
78	    title: truncated,
79	    description: restOfLines ? `${overflow}\n\n${restOfLines}` : overflow,
80	  };
81	}
