3	/**
4	 * Resolves the actual theme (light/dark) based on the theme mode setting.
5	 * Handles system theme detection properly.
6	 */
7	export function getActualTheme(
8	  themeMode: ThemeMode | undefined
9	): 'light' | 'dark' {
10	  if (!themeMode || themeMode === ThemeMode.LIGHT) {
11	    return 'light';
12	  }
13	
14	  if (themeMode === ThemeMode.SYSTEM) {
15	    // Check system preference
16	    return window.matchMedia('(prefers-color-scheme: dark)').matches
17	      ? 'dark'
18	      : 'light';
19	  }
20	
21	  // ThemeMode.DARK
22	  return 'dark';
23	}
