1	import { workspacesApi, repoApi } from '@/shared/lib/api';
2	import type { Workspace } from 'shared/remote-types';
3	import { getValidProjectRepoDefaults } from '@/shared/hooks/useProjectRepoDefaults';
4	
5	export interface WorkspaceDefaults {
6	  preferredRepos: Array<{ repo_id: string; target_branch: string | null }>;
7	}
8	
9	/**
10	 * Fetches workspace creation defaults using a project-aware priority chain:
11	 * 1. Scratch project-repo defaults (if projectId provided and valid repos exist)
12	 * 2. Most recent workspace for the same project (if projectId provided)
13	 * 3. Globally most recent workspace
14	 * 4. null (no defaults)
15	 */
16	export async function getWorkspaceDefaults(
17	  remoteWorkspaces: Workspace[],
18	  localWorkspaceIds: Set<string>,
19	  projectId?: string | null
20	): Promise<WorkspaceDefaults | null> {
21	  // Priority 1: Scratch project-repo defaults
22	  if (projectId) {
23	    try {
24	      const allRepos = await repoApi.list();
25	      const availableRepoIds = new Set(allRepos.map((r) => r.id));
26	      const scratchDefaults = await getValidProjectRepoDefaults(
27	        projectId,
28	        availableRepoIds
29	      );
30	      if (scratchDefaults.length > 0) {
31	        return {
32	          preferredRepos: scratchDefaults.map((r) => ({
33	            repo_id: r.repo_id,
34	            target_branch: r.target_branch,
35	          })),
36	        };
37	      }
38	    } catch (err) {
39	      console.warn('Failed to fetch project scratch defaults:', err);
40	    }
41	
42	    // Priority 2: Most recent workspace for the same project
43	    const projectRecent = remoteWorkspaces
44	      .filter(
45	        (w) =>
46	          w.project_id === projectId &&
47	          w.local_workspace_id !== null &&
48	          localWorkspaceIds.has(w.local_workspace_id)
49	      )
50	      .sort(
51	        (a, b) =>
52	          new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime()
53	      )[0];
54	
55	    if (projectRecent?.local_workspace_id) {
56	      try {
57	        const [repos] = await Promise.all([
58	          workspacesApi.getRepos(projectRecent.local_workspace_id),
59	          workspacesApi.get(projectRecent.local_workspace_id),
60	        ]);
61	        return {
62	          preferredRepos: repos.map((r) => ({
63	            repo_id: r.id,
64	            target_branch: r.target_branch,
65	          })),
66	        };
67	      } catch (err) {
68	        console.warn('Failed to fetch project workspace defaults:', err);
69	      }
70	    }
71	  }
72	
73	  // Priority 3: Globally most recent workspace
74	  const mostRecent = remoteWorkspaces
75	    .filter(
76	      (w) =>
77	        w.local_workspace_id !== null &&
78	        localWorkspaceIds.has(w.local_workspace_id)
79	    )
80	    .sort(
81	      (a, b) =>
82	        new Date(b.updated_at).getTime() - new Date(a.updated_at).getTime()
83	    )[0];
84	
85	  if (!mostRecent?.local_workspace_id) {
86	    return null;
87	  }
88	
89	  try {
90	    const [repos] = await Promise.all([
91	      workspacesApi.getRepos(mostRecent.local_workspace_id),
92	      workspacesApi.get(mostRecent.local_workspace_id),
93	    ]);
94	
95	    return {
96	      preferredRepos: repos.map((r) => ({
97	        repo_id: r.id,
98	        target_branch: r.target_branch,
99	      })),
100	    };
101	  } catch (err) {
102	    console.warn('Failed to fetch workspace defaults:', err);
103	    return null;
104	  }
105	}
