1	const ZOOM_STORAGE_KEY = 'vk-zoom-level';
2	const DEFAULT_FONT_SIZE = 16;
3	const MIN_FONT_SIZE = 8;
4	const MAX_FONT_SIZE = 32;
5	const STEP = 1;
6	
7	function loadFontSize(): number {
8	  try {
9	    const stored = localStorage.getItem(ZOOM_STORAGE_KEY);
10	    if (stored) {
11	      const size = Number(stored);
12	      if (size >= MIN_FONT_SIZE && size <= MAX_FONT_SIZE) return size;
13	    }
14	  } catch {
15	    // localStorage may be unavailable
16	  }
17	  return DEFAULT_FONT_SIZE;
18	}
19	
20	function saveFontSize(size: number): void {
21	  try {
22	    if (size === DEFAULT_FONT_SIZE) {
23	      localStorage.removeItem(ZOOM_STORAGE_KEY);
24	    } else {
25	      localStorage.setItem(ZOOM_STORAGE_KEY, String(size));
26	    }
27	  } catch {
28	    // localStorage may be unavailable
29	  }
30	}
31	
32	function applyFontSize(size: number): void {
33	  document.documentElement.style.fontSize = `${size}px`;
34	}
35	
36	let currentFontSize = DEFAULT_FONT_SIZE;
37	
38	export function zoomIn(): void {
39	  currentFontSize = Math.min(currentFontSize + STEP, MAX_FONT_SIZE);
40	  applyFontSize(currentFontSize);
41	  saveFontSize(currentFontSize);
42	}
43	
44	export function zoomOut(): void {
45	  currentFontSize = Math.max(currentFontSize - STEP, MIN_FONT_SIZE);
46	  applyFontSize(currentFontSize);
47	  saveFontSize(currentFontSize);
48	}
49	
50	export function zoomReset(): void {
51	  currentFontSize = DEFAULT_FONT_SIZE;
52	  applyFontSize(currentFontSize);
53	  saveFontSize(currentFontSize);
54	}
55	
56	export function initZoom(): void {
57	  currentFontSize = loadFontSize();
58	  if (currentFontSize !== DEFAULT_FONT_SIZE) {
59	    applyFontSize(currentFontSize);
60	  }
61	}
