871	function RelayCodeInput({
872	  value,
873	  onChange,
874	  disabled,
875	}: {
876	  value: string;
877	  onChange: (nextValue: string) => void;
878	  disabled?: boolean;
879	}) {
880	  const inputsRef = useRef<Array<HTMLInputElement | null>>([]);
881	  const normalizedValue = normalizeEnrollmentCode(value).slice(0, 6);
882	  const characters = useMemo(
883	    () => Array.from({ length: 6 }, (_, index) => normalizedValue[index] ?? ''),
884	    [normalizedValue]
885	  );
886	
887	  const setCharacterAt = (index: number, char: string) => {
888	    const next = [...characters];
889	    next[index] = char;
890	    onChange(next.join(''));
891	  };
892	
893	  return (
894	    <div
895	      className="flex gap-2"
896	      onPaste={(event) => {
897	        const pasted = normalizeEnrollmentCode(
898	          event.clipboardData.getData('text')
899	        ).slice(0, 6);
900	        if (!pasted) {
901	          return;
902	        }
903	
904	        event.preventDefault();
905	        onChange(pasted);
906	        const focusIndex = Math.min(pasted.length, 5);
907	        inputsRef.current[focusIndex]?.focus();
908	      }}
909	    >
910	      {characters.map((char, index) => (
911	        <input
912	          key={index}
913	          ref={(element) => {
914	            inputsRef.current[index] = element;
915	          }}
916	          type="text"
917	          inputMode="text"
918	          autoComplete="one-time-code"
919	          value={char}
920	          maxLength={1}
921	          disabled={disabled}
922	          onChange={(event) => {
923	            const nextChar = normalizeEnrollmentCode(event.target.value).slice(
924	              -1
925	            );
926	            setCharacterAt(index, nextChar);
927	            if (nextChar && index < 5) {
928	              inputsRef.current[index + 1]?.focus();
929	            }
930	          }}
931	          onKeyDown={(event) => {
932	            if (event.key === 'Backspace' && !characters[index] && index > 0) {
933	              inputsRef.current[index - 1]?.focus();
934	            }
935	            if (event.key === 'ArrowLeft' && index > 0) {
936	              event.preventDefault();
937	              inputsRef.current[index - 1]?.focus();
938	            }
939	            if (event.key === 'ArrowRight' && index < 5) {
940	              event.preventDefault();
941	              inputsRef.current[index + 1]?.focus();
942	            }
943	          }}
944	          className="w-10 h-12 rounded-sm border border-border bg-panel text-center font-mono text-lg uppercase text-high focus:outline-none focus:ring-1 focus:ring-brand disabled:opacity-50"
945	        />
946	      ))}
947	    </div>
948	  );
949	}
